// CS2 external wallhack + aimbot + auto bhop (ESP overlay) — Visual Studio, x64.
//
// Reads the cs2.exe process with ReadProcessMemory (no injection), walks the
// entity list every frame, projects player positions through the view matrix
// and draws boxes / names / health on a click-through overlay window.
// The aimbot steers the crosshair onto the nearest enemy's head with relative
// mouse movement (SendInput) — read-only against the game process.
//
// Auto bhop runs on its own worker thread (see "auto bhop" below): Input mode
// injects Space with SendInput, Memory mode writes IN_JUMP into m_nButtons —
// the only writes the process makes, and only while that toggle is on.
//
// Build: open cs2-wallhack.sln, pick x64 Debug or Release, press F5.
// Run:   run the cheat whenever — if CS2 isn't running it asks whether to open
//        it (declining just waits for the game), then joins as before.
// Keys:  INSERT = open the menu, click Wallhack / Aimbot / Auto Bhop to toggle,
//        END = exit.
// Menu:  Smoothness = aimbot speed (1 = snappy, 50 = slow drift); Reaction =
//        ms before the aimbot starts on a newly appeared target (0 = instant).
//
// Note: the overlay is a WS_EX_TOPMOST layered window. It draws over borderless /
// windowed fullscreen; exclusive fullscreen may hide it. Set CS2 to "Fullscreen
// Windowed" if boxes don't appear.

