#include <Gdiplus.h>      // skeleton ESP: antialiased float-width strokes
#pragma comment(lib, "Gdiplus.lib")
#include <Shellapi.h>     // ShellExecuteA: open the configs folder
#pragma comment(lib, "Shell32.lib")
#include <shlobj.h>       // SHGetFolderPathA: Documents dir (no admin needed)

#include <cstdint>
