// GDI+ drives the skeleton strokes: its Pen takes a float width and the lines
// antialias, so every 0.1px step on the Skel Width bar renders as slightly
// wider coverage. A GDI pen can only be a whole device-pixel wide — the value
// had to round and visibly snapped between steps. 0 = never started, the draw
// path falls back to the integer pen.
static ULONG_PTR g_gdiplusTok = 0;

