// auto bhop: a jump is an atomic release+press pulse (one SendInput call) so
// the game always gets a fresh press edge — a lone keydown while the physical
// key is already down repeats-flagged and is ignored — and the key state ends
// where the physical key has it
static constexpr DWORD kBhopTickMs   = 16;    // input-mode jumpHeld release bookkeeping
static constexpr DWORD kBhopPollMs   = 1;     // worker poll cadence (timeBeginPeriod(1))
static constexpr DWORD kBhopAttachRetryMs = 500; // re-attach attempts while waiting for cs2
static constexpr DWORD kSpaceGraceMs = 500; // keep "Space held" true across our own pulse
                                            // events — the physical key raises no new event
                                            // then; kept below hang time (~700 ms) so a
                                            // genuine mid-air release still stops hops
static constexpr int kChainFailTicks = 200; // consecutive failed chain polls before a
                                            // candidate is blamed (~200 ms; death/respawn
                                            // transitions must not advance or disable)
// speculative pre-jump: this air time is predicted from the PREVIOUS one —
// takeoff stamps the clock, the last completed air duration gives the
// touchdown, and the pulses fire as it crosses each threshold. The input
// chain polls in ~1 ms steps so a crossing fires sub-ms late, and hop-to-hop
// air times differ only by that poll jitter — no physics reads to go stale;
// the landing pulse stays as the fallback — a bad prediction costs nothing
static constexpr float kPreLeads[] = { 15.f, 9.f, 3.f };
static constexpr int   kPreN       = 3;
static constexpr DWORD kBhopRetryMs = 600;  // alive-time one pawn source may fail before
                                            // its candidates start advancing (short: a
                                            // correct list walks a live handle in a tick,
                                            // and a wrong scan candidate must not burn
                                            // seconds of every enable cycle)

// player bone array (verified live against this client build): the scene node
// holds a pointer whose block stores each transform 0x60 apart with the
// translation at +0x40; only the first ~37 entries belong to this pawn
static constexpr uintptr_t kBoneArrayOff  = 0x1C0;  // scene node -> array base
static constexpr int       kBoneStride    = 0x60;
static constexpr int       kBonePosOff    = 0x40;
static constexpr int       kBoneReadBytes = 0xF00;  // covers indices 0..37

// skeleton joints, remapped from the live [bdbg] geometry dump (height +
// distance-from-spine over four poses on this build): spine and head were
// still correct, the arm and leg slots were stale after the animgraph bone
// re-index — arms chain clavicle -> elbow -> rifle-grip hands (the hand pair
// has matching lateral distance in every dump: both hands on one weapon).
// Legs: the knee/foot indices are the one part of the table that differs
// per player model — live dumps show one model reading knees 27/31 with a
// single floor bone at 28, another reading 27 at neck height with two floor
// bones at 24/25. The table pair below is only the first guess; the read
// loop reclassifies knees/feet from the window geometry when it doesn't
// match this model (see the leg block after the joint loop).
enum {
    kBPelvis = 0, kBChest = 1, kBNeck = 2, kBHead = 8,
    kBShL = 4,  kBElbL = 19, kBHandL = 22,
    kBShR = 23, kBElbR = 21, kBHandR = 17,
    kBKneeL = 27, kBFootL = 28, kBKneeR = 31, kBFootR = 28,
};
// draw order used by EspPlayer::bx/by and DrawEsp's line segments
static constexpr int kSkelJoints[] = { kBHead, kBNeck, kBChest, kBPelvis,
                                       kBShL, kBElbL, kBHandL,
                                       kBShR, kBElbR, kBHandR,
                                       kBKneeL, kBFootL, kBKneeR, kBFootR };
static constexpr int kSkelN    = 14;
static constexpr int kSkelHead = 0;   // head's position inside kSkelJoints
static constexpr int kSkelChest = 2;  // chest/neck/knee positions (hitbox checklist)
static constexpr int kSkelPelv  = 3;
static constexpr int kSkelKneeL = 10;
static constexpr int kSkelKneeR = 12;
// body segments shared by the ESP skeleton and the trigger's silhouette test
static constexpr int kSkelSegs[][2] = {
    { 0, 1 }, { 1, 2 }, { 2, 3 }, { 4, 7 },         // spine, shoulders
    { 4, 5 }, { 5, 6 }, { 7, 8 }, { 8, 9 },         // arms
    { 3, 10 }, { 10, 11 }, { 3, 12 }, { 12, 13 }    // legs
};
static constexpr int kSkelSegN = sizeof(kSkelSegs) / sizeof(kSkelSegs[0]);
