// feature colours edited by the in-menu RGB picker; row features own a swatch
// on their row and point into kCol through kColRow — the two box card colours
// (kColBox, kColBoxFill) are edited inside the card and skip the row loops
struct Rgb { unsigned char r, g, b; };
static COLORREF Cref(const Rgb& c) {
    // pure black is the overlay's transparency key: floor it to near-black so
    // a zeroed colour still renders (and its swatch stays clickable) instead
    // of vanishing and stranding the picker
    if (c.r == 0 && c.g == 0 && c.b == 0) return RGB(1, 1, 1);
    return RGB(c.r, c.g, c.b);
}
