// Aimbot settings are stored PER WEAPON CLASS: the dropdown on the right of
// the AimHack header picks which class the Smoothness / Reaction / Aimbot FOV
// sliders edit. GLOBAL is slot 0 and is always set — it is what every class
// that has not been set up falls back to, and what any weapon outside the
// five classes (knife, grenades, LMGs, taser) runs on.
enum { kWepGlobal = 0, kWepPistol, kWepSmg, kWepSniper, kWepRifle, kWepShotgun,
       kWepCount };
