// on-screen telling-off for blocked activations (console + log too)
static void SafeNotify(const char* msg) {
    strncpy_s(g_safeMsg, sizeof(g_safeMsg), msg, _TRUNCATE);
    g_safeMsgMs = GetTickCount();
    printf("[*] safe: %s\n", msg);
    Logf("[safe] %s\n", msg);
}
static AimTune g_aimTune[kWepCount] = { { 5.0f, 0, 6 }, {}, {}, {}, {}, {} };
static bool    g_aimTuneSet[kWepCount] = { true, false, false, false, false, false };
static int     g_wepSel      = kWepGlobal;  // class the AimHack sliders edit (UI thread)
static bool    g_wepDropOpen = false;       // its dropdown list shown (UI thread only)

// class of the weapon in hand, from the definition index the weapon read
// already publishes each frame (CS2 item definition indices, same table the
// trigger's damage gate uses); anything unmapped falls to Global
static int WeaponClass(uint16_t def) {
    switch (def) {
    case  1: case  2: case  3: case  4: case 30: case 32: case 36:
    case 61: case 63: case 64:                        // pistols, R8, CZ75
        return kWepPistol;
    case 17: case 19: case 23: case 24: case 26:
    case 33: case 34:                                 // MAC-10, P90, MP5-SD,
        return kWepSmg;                               // UMP, Bizon, MP7, MP9
    case  9: case 11: case 38: case 40:               // AWP, G3SG1, SCAR, SSG
        return kWepSniper;
    case  7: case  8: case 10: case 13: case 16:
    case 39: case 60:                                 // AK, AUG, FAMAS, Galil,
        return kWepRifle;                             // M4A4, SG553, M4A1-S
    case 25: case 29: case 35:                        // XM1014, MAG-7, Nova
        return kWepShotgun;
    default:
        return kWepGlobal;
    }
}
// what a class runs on: its own values once it has been edited, otherwise the
// GLOBAL slot — an untouched class therefore always tracks Global live
static const AimTune& AimTuneFor(int cls) {
    return (cls > kWepGlobal && g_aimTuneSet[cls]) ? g_aimTune[cls]
                                                   : g_aimTune[kWepGlobal];
}
// the slot a slider write goes to: the first edit on a class copies Global
// over and detaches it, so the slider never jumps under the cursor
static AimTune& AimTuneEdit(int cls) {
    if (cls > kWepGlobal && !g_aimTuneSet[cls]) {
        g_aimTune[cls] = g_aimTune[kWepGlobal];
        g_aimTuneSet[cls] = true;
    }
    return g_aimTune[cls];
}
// the settings the aimbot itself runs this frame: the class in hand
static const AimTune& AimTuneHeld() { return AimTuneFor(WeaponClass(g_wepDef)); }
// sniper scope check: while a sniper is in hand the aimbot and the triggerbot
// act only on a SCOPED weapon. GLOBAL holds the default, the Snipers tab can
// override it — the toggle lives on those two tabs only, because a sniper is
// the one weapon class that can scope, so no other class has anything to say.
static bool g_scopeOnly[kWepCount]   = { true, true, true, true, true, true };
static bool g_scopeOnlySet[kWepCount] = { true, false, false, false, false, false };
static bool ScopeOnlyFor(int cls) {
    return (cls > kWepGlobal && g_scopeOnlySet[cls]) ? g_scopeOnly[cls]
                                                     : g_scopeOnly[kWepGlobal];
}
// sniper settings card: the Trigger tab's "Sniper Settings" button opens it —
// it holds the scope check above plus the autoscope switch (UI thread only)
static bool g_sniperPanelOpen = false;
// autoscope: zoom a held sniper in the moment a visible enemy enters the
// aimbot FOV cone, so the scope check has its scope the instant a fight starts
static bool g_autoScope = false;
// hitbox checklist: bitmask of what the aimbot may steer to (bit per kHb*);
// each frame it takes the closest SELECTED point to the crosshair
enum { kHbHead = 0, kHbNeck = 1, kHbStomach = 2, kHbLegs = 3 };
static int   g_aimHbMask = (1 << kHbHead);  // default: head only (old behaviour)
static bool  g_aimPreferHead = false;  // head wins outright whenever its bone read sane
static bool  g_aimCfgOpen = false;   // aimbot sub-panel open (arrow button on its row)
static const char* kAimHbName[] = { "Head", "Neck", "Stomach", "Legs" };
static bool                g_fovCircleOn = false; // draw the aimbot FOV circle
static bool                g_menuOpen = false;
static int                 g_cursorBoost = 0;   // how many ShowCursor(TRUE) calls we owe back
static std::vector<EspPlayer> g_players;

// one entry per observer whose target handle resolves to the local pawn;
// mode is the game's ObserverMode_t, kept so the list can say HOW they watch
struct Spectator {
    char    name[32];
    int     slot;      // controller index, for a fallback label
    uint8_t mode;      // game's ObserverMode_t (1 deathcam .. 5 chase)
    bool    enemy;
};
static std::vector<Spectator> g_specs;

// auto bhop state: g_bhopOn is the menu toggle (written on the UI thread, read
// by the worker), g_bhopEnabled is the worker gate the button controls, and the
// rest is worker -> GUI status published under g_bhopMtx
static std::atomic<bool>   g_bhopOn{false};      // menu toggle: feature requested ON
static std::atomic<bool>   g_bhopEnabled{false}; // gate: worker runs while true
static std::thread         g_bhopThread;
static std::atomic<bool>   g_bhopMemoryMode{false}; // false = Input, true = Memory
static bool                g_bhopDropOpen = false;   // Jump Mode list shown (UI thread only)
static std::mutex          g_bhopMtx;
static std::atomic<bool>   g_bhopAttached{false}; // process + offsets resolved
static bool                g_bhopError = false;      // auto-disabled, message below
static char                g_bhopStatus[160] = "Not attached";

// off-screen back buffer: complete frames are blitted to the overlay in one
// operation so the color-keyed layer never shows a half-drawn (transparent) frame
static HDC      g_memDc  = nullptr;
static HBITMAP  g_memBmp = nullptr;
static HBITMAP  g_memOld = nullptr;
static void*    g_memBits = nullptr;  // DIB section pixels: the GUI crossfade reads/writes in place
static int      g_memW   = 0;
static int      g_memH   = 0;

// menu cursor position (overlay client coords): synced from the player's real
// OS pointer while the menu is open (raw input also feeds it — the sync
// overwrites); g_clickQueued latches a click received as a window message
static POINT    g_uiPos{ 0, 0 };
static POINT    g_menuPos{ 80, 80 }; // menu panel position on the overlay (dragged by its header)
static bool     g_clickQueued = false;
static bool     g_rawRegistered = false;  // raw input sink available?
static DWORD    g_lastRawMs     = 0;      // last WM_INPUT seen (raw liveness)
static int      g_wheelDelta = 0;         // wheel delta latched by WM_INPUT (120 = one notch)

// diagnostic log: cs2-wh.log next to the exe, opened/append/closed per line so
// the file stays readable by other tools while the cheat is running
static void Logf(const char* fmt, ...) {
    FILE* f = nullptr;
    if (fopen_s(&f, "cs2-wh.log", "a") != 0 || !f) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(f, fmt, ap);
    va_end(ap);
    fclose(f);
}

// ---------------------------------------------------------------------------
// display scale
// ---------------------------------------------------------------------------
// The screen runs at 150% scaling; the UI is authored in 96-dpi design pixels
// and U() converts them to device pixels, so the panel keeps its proportions
// while every glyph and shape is rasterised 1:1 instead of being bitmap-
// stretched by the compositor — that upscale was the fuzz over everything.
static float UiScale() {
    static const float s = [] {
        HDC   dc  = GetDC(nullptr);
        const int dpi = GetDeviceCaps(dc, LOGPIXELSX);
        ReleaseDC(nullptr, dc);
        return (dpi > 0 ? dpi : 96) / 96.0f;
    }();
    return s;
}
static int U(float px) { return static_cast<int>(px * UiScale() + (px >= 0.0f ? 0.5f : -0.5f)); }
static int U(int px)   { return U(static_cast<float>(px)); }

// every overlay font is built here: design px -> device px, ClearType quality
// so text renders crisp at 1:1 (the old DEFAULT_QUALITY faces read mushy)
static HFONT MakeFont(int px, int weight, const char* face = "Segoe UI") {
    if (weight < FW_BOLD) weight = FW_BOLD;   // every text in the cheat renders bold
    return CreateFontA(U(px), 0, 0, 0, weight, FALSE, FALSE, FALSE, DEFAULT_CHARSET,
                       OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, CLEARTYPE_QUALITY,
                       DEFAULT_PITCH | FF_DONTCARE, face);
}

// ---------------------------------------------------------------------------
// antialiased shapes
// ---------------------------------------------------------------------------
// GDI's RoundRect/Ellipse rasterize hard stair-steps (the jagged toggle edges).
// These route the same geometry through GDI+ with SmoothingModeAntiAlias; a
// Graphics built from the DC inherits the menu's world transform and the row
// viewport clip, so zoom and clipping apply unchanged. CLR_INVALID skips a pass
// (GDI's NULL_PEN / NULL_BRUSH equivalent).
static Gdiplus::Color AaColor(COLORREF c) {
    return Gdiplus::Color(GetRValue(c), GetGValue(c), GetBValue(c));
}

static void AaRoundRect(HDC dc, int l, int t, int r, int b, int ew, int eh,
                        COLORREF fill, COLORREF edge) {
    if (r <= l || b <= t) return;
    Gdiplus::Graphics g(dc);
    g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
    const float x = static_cast<float>(l), y = static_cast<float>(t);
    const float w = static_cast<float>(r - l), h = static_cast<float>(b - t);
    float rx = ew * 0.5f, ry = eh * 0.5f;      // GDI corner args are an ellipse
    if (rx * 2.0f > w) rx = w * 0.5f;          // diameter, not a radius
    if (ry * 2.0f > h) ry = h * 0.5f;
    Gdiplus::GraphicsPath path;
    if (rx > 0.5f && ry > 0.5f) {
        path.AddArc(x,              y,               rx * 2, ry * 2, 180, 90);
        path.AddArc(x + w - rx * 2, y,               rx * 2, ry * 2, 270, 90);
        path.AddArc(x + w - rx * 2, y + h - ry * 2,  rx * 2, ry * 2,   0, 90);
        path.AddArc(x,              y + h - ry * 2,  rx * 2, ry * 2,  90, 90);
        path.CloseFigure();
    } else {
        path.AddRectangle(Gdiplus::RectF(x, y, w, h));
    }
    if (fill != CLR_INVALID) {
        const Gdiplus::SolidBrush br(AaColor(fill));
        g.FillPath(&br, &path);
    }
    if (edge != CLR_INVALID) {
        const Gdiplus::Pen pen(AaColor(edge), 1.0f);
        g.DrawPath(&pen, &path);
    }
}

static void AaEllipse(HDC dc, int l, int t, int r, int b,
                      COLORREF fill, COLORREF edge) {
    if (r <= l || b <= t) return;
    Gdiplus::Graphics g(dc);
    g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
    const Gdiplus::RectF rc(static_cast<float>(l), static_cast<float>(t),
                            static_cast<float>(r - l), static_cast<float>(b - t));
    if (fill != CLR_INVALID) {
        const Gdiplus::SolidBrush br(AaColor(fill));
        g.FillEllipse(&br, rc);
    }
    if (edge != CLR_INVALID) {
        const Gdiplus::Pen pen(AaColor(edge), 1.0f);
        g.DrawEllipse(&pen, rc);
    }
}

// GDI RoundRect/Ellipse callers keep their exact idiom — select the brush
// and pen, then draw the shape — and land here instead: the selected
// objects are read back and the same geometry routed through the AA
// helpers, so every corner and dot rasterizes smooth. NULL_BRUSH/NULL_PEN
// map to CLR_INVALID (skip that pass), matching GDI semantics
static COLORREF SelShapeFill(HDC dc) {
    const HGDIOBJ br = GetCurrentObject(dc, OBJ_BRUSH);
    LOGBRUSH lb{};
    if (!br || GetObject(br, sizeof(lb), &lb) <= 0) return CLR_INVALID;
    return lb.lbStyle == BS_SOLID ? lb.lbColor : CLR_INVALID;
}
static COLORREF SelShapeEdge(HDC dc) {
    const HGDIOBJ pn = GetCurrentObject(dc, OBJ_PEN);
    LOGPEN lp{};
    if (!pn || GetObject(pn, sizeof(lp), &lp) <= 0) return CLR_INVALID;
    return lp.lopnStyle == PS_NULL ? CLR_INVALID : lp.lopnColor;
}
static void AaRoundRectSel(HDC dc, int l, int t, int r, int b, int ew, int eh) {
    AaRoundRect(dc, l, t, r, b, ew, eh, SelShapeFill(dc), SelShapeEdge(dc));
}
static void AaEllipseSel(HDC dc, int l, int t, int r, int b) {
    AaEllipse(dc, l, t, r, b, SelShapeFill(dc), SelShapeEdge(dc));
}

// ---------------------------------------------------------------------------
// memory helpers
// ---------------------------------------------------------------------------
template <typename T>
T Read(uintptr_t address) {
    T value{};
    if (g_process)
        ReadProcessMemory(g_process, reinterpret_cast<LPCVOID>(address), &value, sizeof(T), nullptr);
    return value;
}

static bool ReadBytes(uintptr_t address, void* dst, size_t size) {
    if (!g_process) return false;
    SIZE_T done = 0;
    return ReadProcessMemory(g_process, reinterpret_cast<LPCVOID>(address), dst, size, &done) && done == size;
}

static DWORD FindProcessId(const wchar_t* exeName) {
    PROCESSENTRY32W pe{};
    pe.dwSize = sizeof(pe);
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, exeName) == 0) {
                pid = pe.th32ProcessID;
                break;
            }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t ModuleBase(DWORD pid, const wchar_t* moduleName) {
    MODULEENTRY32W me{};
    me.dwSize = sizeof(me);
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, moduleName) == 0) {
                base = reinterpret_cast<uintptr_t>(me.modBaseAddr);
                break;
            }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

// Entity list traversal: chunk pointer lives at list + 0x10 + 8*(index >> 9),
// entities are 0x70 bytes apart inside a chunk (verified live against the current
// build; the commonly published 0x78 reads mid-structure garbage).
static uintptr_t EntityByIndex(uintptr_t entityList, uint32_t index) {
    index &= 0x7FFF;
    if (!entityList || index == 0) return 0;
    uintptr_t chunk = Read<uintptr_t>(entityList + 0x10 + 0x8ULL * (index >> 9));
    if (!chunk) return 0;
    return Read<uintptr_t>(chunk + 0x70ULL * (index & 0x1FF));
}

// ---------------------------------------------------------------------------
// auto bhop worker
// ---------------------------------------------------------------------------
// Opens its own handle to cs2.exe (PROCESS_VM_READ | PROCESS_VM_WRITE) and
// resolves what it needs from client.dll by pattern scanning it: the dw*
// globals from rip-relative loads in code, the netvar fields from their schema
// name strings. Every candidate is cross-checked against the live process and
// bhop_offsets.hpp supplies fallback values when a scan misses — if neither
// candidate validates, the feature auto-disables and says why on the status row.
//
// Edge trigger: while Space is held, the air->ground transition fires one jump
// tick (press), released again as soon as the player is airborne — Input mode
// does it with SendInput key events, Memory mode by setting IN_JUMP in the
// pawn's movement-services button state for one tick.

static bool BhopRead(HANDLE proc, uintptr_t addr, void* dst, size_t size) {
    SIZE_T done = 0;
    return proc && ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(addr), dst,
                                     size, &done) && done == size;
}

template <typename T>
static bool BhopReadT(HANDLE proc, uintptr_t addr, T& out) {
    return BhopRead(proc, addr, &out, sizeof(T));
}

static bool BhopWrite32(HANDLE proc, uintptr_t addr, uint32_t value) {
    SIZE_T done = 0;
    return proc && WriteProcessMemory(proc, reinterpret_cast<LPVOID>(addr), &value,
                                      sizeof(value), &done) && done == sizeof(value);
}

static bool BhopUserPtr(uintptr_t p) {
    return p > 0x10000ull && p < 0x00007FFFFFFFFFFFull;
}

// one resolved field with up to three candidates: scan hits pushed to the
// front, the fallback file always retained as the last one
struct BhopField {
    const char*    name;
    std::ptrdiff_t cand[3];
    int            n;
    int            cur;
};

struct BhopOffsets {
    BhopField entityList;
    BhopField localPawn;
    BhopField controller;
    BhopField flags;
    BhopField moveSvc;
    BhopField buttons;
    BhopField pawnAlive;
    BhopField pawnHandle;
    BhopField isLocalCtrl;
    BhopField sceneNode;
    BhopField health;
};

static void BhopStatusf(bool error, const char* fmt, ...) {
    char body[160];
    va_list ap;
    va_start(ap, fmt);
    vsprintf_s(body, fmt, ap);
    va_end(ap);
    std::lock_guard<std::mutex> lock(g_bhopMtx);
    g_bhopError = error;
    sprintf_s(g_bhopStatus, "%s", body);
}

// auto-disable: latch the reason, show it in the menu, drop the worker gate
static void BhopDisable(const char* fmt, ...) {
    char body[160];
    va_list ap;
    va_start(ap, fmt);
    vsprintf_s(body, fmt, ap);
    va_end(ap);
    BhopStatusf(true, "%s", body);
    g_bhopOn = false;
    g_bhopEnabled = false;
    Logf("[bhop] auto-disabled: %s\n", body);
    printf("[-] auto bhop: %s\n", body);
}

// gate-aware sleep: returns false when the toggle was turned off mid-sleep
static bool BhopSleep(DWORD ms) {
    const DWORD end = GetTickCount() + ms;
    while (g_bhopEnabled.load()) {
        const DWORD now = GetTickCount();
        if (static_cast<int32_t>(now - end) >= 0) return true;
        Sleep(5);
    }
    return false;
}

// one jump: release+press queued as a single atomic pair — no sleep between
// them. The press then fires the same tick we detect touchdown instead of a
// full tick later, so the jump lands on ground-tick 1 (with a sleep the engine
// only saw the fresh press at the tick after that: extra ground ticks = friction
// = lost speed = missed perfects). The queue preserves order, the engine's
// event-driven input takes the press after the release as fresh, and the state
// ends on key-down — identical to the physical hold — so GetAsyncKeyState stays
// truthful across the whole air time
static void BhopSendJumpPulse() {
    INPUT in[2]{};
    in[0].type = in[1].type = INPUT_KEYBOARD;
    in[0].ki.wVk = in[1].ki.wVk = VK_SPACE;
    in[0].ki.dwFlags = KEYEVENTF_KEYUP;
    in[1].ki.dwFlags = 0;                   // the press
    SendInput(2, in, sizeof(INPUT));
}

// --- pattern scanning -------------------------------------------------------

// SizeOfImage straight out of the remote PE headers — bounds for scan hits
static bool BhopImageSize(HANDLE proc, uintptr_t base, size_t& out) {
    IMAGE_DOS_HEADER dos{};
    if (!BhopReadT(proc, base, dos) || dos.e_magic != IMAGE_DOS_SIGNATURE) return false;
    IMAGE_NT_HEADERS64 nt{};
    if (!BhopReadT(proc, base + dos.e_lfanew, nt) ||
        nt.Signature != IMAGE_NT_SIGNATURE)
        return false;
    out = nt.OptionalHeader.SizeOfImage;
    return out > 0x1000 && out < 0x40000000;
}

static void BhopParseIda(const char* ida, std::vector<int>& out) {
    out.clear();
    const char* p = ida;
    while (*p) {
        while (*p == ' ') ++p;
        if (!*p) break;
        if (p[0] == '?' && (p[1] == '?' || p[1] == ' ' || p[1] == '\0')) {
            out.push_back(-1);                    // wildcard byte
            p += (p[1] == '?') ? 2 : 1;
            continue;
        }
        auto hex = [](char c) -> int {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return c - 'a' + 10;
            if (c >= 'A' && c <= 'F') return c - 'A' + 10;
            return -1;
        };
        const int hi = hex(p[0]), lo = hex(p[1]);
        if (hi < 0 || lo < 0) return;
        out.push_back(hi * 16 + lo);
        p += 2;
    }
}

// resolve one code signature into the RVA of the global it loads; appends up
// to two distinct, in-range targets
static void BhopScanCode(const std::vector<uint8_t>& img, const bhop::CodeSig& sig,
                         std::ptrdiff_t* out, int& n, int cap,
                         std::ptrdiff_t lo, std::ptrdiff_t hi) {
    std::vector<int> pat;
    BhopParseIda(sig.ida, pat);
    if (pat.empty() || img.size() < pat.size()) return;
    const uint8_t* d = img.data();
    const size_t last = img.size() - pat.size();
    for (size_t i = 0; i <= last && n < cap; ++i) {
        size_t j = 0;
        for (; j < pat.size(); ++j)
            if (pat[j] >= 0 && d[i + j] != static_cast<uint8_t>(pat[j])) break;
        if (j != pat.size()) continue;
        if (i + static_cast<size_t>(sig.dispAt) + 4 > img.size()) continue;
        int32_t disp = 0;
        memcpy(&disp, d + i + sig.dispAt, sizeof(disp));
        const std::ptrdiff_t target =
            static_cast<std::ptrdiff_t>(i) + sig.instrLen + disp;
        if (target < lo || target > hi) continue;
        bool dup = false;
        for (int k = 0; k < n; ++k) dup = dup || out[k] == target;
        if (!dup) out[n++] = target;
    }
}

// netvar offset from its schema name string: find "m_fFlags\0", then the
// SchemaClassFieldData { name*, type*, offset u32 } whose name* points at it
static bool BhopScanNetvar(const std::vector<uint8_t>& img, uintptr_t clientBase,
                           const bhop::NetvarSpec& spec, std::ptrdiff_t& out) {
    const size_t nameLen = strlen(spec.name);
    size_t strRva = static_cast<size_t>(-1);
    if (img.size() > nameLen) {
        for (size_t i = 0; i + nameLen + 1 <= img.size(); ++i) {
            if (memcmp(img.data() + i, spec.name, nameLen) == 0 &&
                img[i + nameLen] == '\0') {
                strRva = i;
                break;
            }
        }
    }
    if (strRva == static_cast<size_t>(-1)) return false;

    const uint64_t want = static_cast<uint64_t>(clientBase + strRva);
    for (size_t i = 0; i + 0x18 <= img.size(); i += 8) {
        uint64_t q = 0;
        memcpy(&q, img.data() + i, sizeof(q));
        if (q != want) continue;
        uint32_t off = 0;
        memcpy(&off, img.data() + i + 0x10, sizeof(off));
        if (off >= spec.lo && off <= spec.hi) {
            out = static_cast<std::ptrdiff_t>(off);
            return true;
        }
    }
    return false;
}

// append a distinct, non-zero candidate (capped at three)
static void BhopAddCand(BhopField& f, std::ptrdiff_t v) {
    if (v == 0) return;
    for (int i = 0; i < f.n; ++i)
        if (f.cand[i] == v) return;
    if (f.n < 3) f.cand[f.n++] = v;
}

static void BhopFieldInit(BhopField& f, const char* name, std::ptrdiff_t fallback) {
    f.name = name;
    f.n    = 0;
    f.cur  = 0;
    f.cand[0] = f.cand[1] = f.cand[2] = 0;
    BhopAddCand(f, fallback);             // fallback is always a candidate
}

// move a scan hit to the front of the candidate list (scan wins over fallback)
static void BhopPushFront(BhopField& f, std::ptrdiff_t v) {
    if (v == 0) return;
    const std::ptrdiff_t keep[3] = { f.cand[0], f.cand[1], f.cand[2] };
    const int kn = f.n;
    f.n = 0;
    f.cur = 0;
    BhopAddCand(f, v);
    for (int k = 0; k < kn; ++k) BhopAddCand(f, keep[k]);
}

static bool BhopResolve(HANDLE proc, uintptr_t client, size_t imageSize,
                        const std::vector<uint8_t>& img, BhopOffsets& out,
                        bool& scanned) {
    scanned = false;
    BhopFieldInit(out.entityList, "dwEntityList", bhop::kFallback.entityList);
    BhopFieldInit(out.localPawn, "dwLocalPlayerPawn", bhop::kFallback.localPawn);
    BhopFieldInit(out.controller, "dwLocalPlayerController", bhop::kFallback.controller);
    BhopFieldInit(out.flags, "m_fFlags", bhop::kFallback.flags);
    BhopFieldInit(out.moveSvc, "m_pMovementServices", bhop::kFallback.moveSvc);
    BhopFieldInit(out.buttons, "m_nButtons", bhop::kFallback.buttons);
    BhopFieldInit(out.pawnAlive, "m_bPawnIsAlive", bhop::kFallback.pawnAlive);
    BhopFieldInit(out.pawnHandle, "m_hPlayerPawn", bhop::kFallback.pawnHandle);
    BhopFieldInit(out.isLocalCtrl, "m_bIsLocalPlayerController", bhop::kFallback.isLocalCtrl);
    BhopFieldInit(out.sceneNode, "m_pGameSceneNode", bhop::kFallback.sceneNode);
    BhopFieldInit(out.health, "m_iHealth", bhop::kFallback.health);

    auto scanInto = [&](BhopField& f, const bhop::CodeSig* sigs, size_t count,
                        std::ptrdiff_t lo) {
        if (img.empty()) return;
        std::ptrdiff_t hits[2];
        int n = 0;
        for (size_t s = 0; s < count && n < 2; ++s)
            BhopScanCode(img, sigs[s], hits, n, 2, lo,
                         static_cast<std::ptrdiff_t>(imageSize));
        for (int i = n - 1; i >= 0; --i) BhopPushFront(f, hits[i]);
        if (n > 0) scanned = true;
    };

    scanInto(out.entityList, bhop::kEntityListSigs,
             sizeof(bhop::kEntityListSigs) / sizeof(bhop::kEntityListSigs[0]), 0x1000);
    scanInto(out.localPawn, bhop::kLocalPawnSigs,
             sizeof(bhop::kLocalPawnSigs) / sizeof(bhop::kLocalPawnSigs[0]), 0x1000);

    if (!img.empty()) {
        const size_t netCount = sizeof(bhop::kNetvars) / sizeof(bhop::kNetvars[0]);
        std::ptrdiff_t found[8] = { 0 };
        for (size_t i = 0; i < netCount && i < 8; ++i)
            if (BhopScanNetvar(img, client, bhop::kNetvars[i], found[i]))
                scanned = true;
        auto push = [&](BhopField& f, std::ptrdiff_t v) {
            if (v == 0) return;
            BhopPushFront(f, v);
            scanned = true;
        };
        push(out.flags, found[0]);
        push(out.moveSvc, found[1]);
        push(out.buttons, found[2]);
        push(out.pawnAlive, found[3]);
        push(out.pawnHandle, found[4]);
        push(out.isLocalCtrl, found[5]);
    }
    return out.entityList.n > 0 && out.localPawn.n > 0 && out.controller.n > 0 &&
           out.flags.n > 0 && out.moveSvc.n > 0 && out.buttons.n > 0 &&
           out.pawnAlive.n > 0 && out.pawnHandle.n > 0 && out.isLocalCtrl.n > 0 &&
           out.sceneNode.n > 0 && out.health.n > 0;
}

// try the next candidate of a field; false when exhausted (caller disables)
static bool BhopAdvance(BhopField& f) {
    if (f.cur + 1 >= f.n) return false;
    ++f.cur;
    Logf("[bhop] %s -> candidate %d (0x%llX) after validation miss\n", f.name,
         f.cur, static_cast<unsigned long long>(f.cand[f.cur]));
    return true;
}

// proc-aware entity list walk: the worker has its own handle, so it cannot
// reuse the ESP's g_process-based EntityByIndex
static uintptr_t BhopEntityByIndex(HANDLE proc, uintptr_t entityList, uint32_t index) {
    index &= 0x7FFF;
    if (!entityList || !index) return 0;
    uintptr_t chunk = 0, ent = 0;
    if (!BhopReadT(proc, entityList + 0x10 + 0x8ULL * (index >> 9), chunk) || !chunk)
        return 0;
    if (!BhopReadT(proc, chunk + 0x70ULL * (index & 0x1FF), ent)) return 0;
    return ent;
}

// resolve-time cross-check against the live process: an unverified signature
// can match the wrong global and read plausible garbage, so a candidate that
// reads non-null must look like what it claims to be. Null reads are
// inconclusive (menu / not connected). The pawn chain itself is not checked
// here: dead players' dwLocalPlayerPawn holds a stale freed object that fails
// every static check, so chain validation runs only at runtime, gated on the
// controller reporting the player spawned.
static bool BhopValidateLive(HANDLE proc, uintptr_t client, BhopOffsets& off) {
    // entity list: non-null global must be a user pointer
    for (int guard = 0; guard < 4; ++guard) {
        uintptr_t list = 0;
        if (!BhopReadT(proc, client + off.entityList.cand[off.entityList.cur], list))
            break;                                  // unreadable: runtime checks decide
        if (list == 0) break;                       // inconclusive
        if (BhopUserPtr(list)) break;
        if (!BhopAdvance(off.entityList)) return false;
    }
    // controller: non-null must flag itself as THE local controller
    for (int guard = 0; guard < 4; ++guard) {
        uintptr_t ctrl = 0;
        if (!BhopReadT(proc, client + off.controller.cand[off.controller.cur], ctrl))
            break;
        if (ctrl == 0) break;                       // menu: inconclusive
        uint8_t isLocal = 0;
        if (BhopUserPtr(ctrl) && !(ctrl & 7) &&
            BhopReadT(proc, ctrl + off.isLocalCtrl.cand[off.isLocalCtrl.cur], isLocal) &&
            isLocal == 1)
            break;
        if (!BhopAdvance(off.controller)) return false;
    }
    return true;
}

// --- the worker -------------------------------------------------------------

static void BhopWorker() {
    Logf("[bhop] worker started (mode=%s)\n",
         g_bhopMemoryMode.load() ? "memory" : "input");
    BhopStatusf(false, "starting...");

    HANDLE     proc = nullptr;
    bool       writable = false;
    uintptr_t  client = 0;
    size_t     imageSize = 0;
    bool       resolved = false;
    BhopOffsets off{};
    bool       prevOnGround = true;
    bool       jumpHeld = false;
    bool       jumpByMemory = false;
    uintptr_t  memBtnAddr = 0;
    DWORD      releaseAt = 0;
    bool       spaceHeld = false;
    DWORD      lastOurKeyMs = 0;
    int        pawnReadFails = 0;
    DWORD      checkListAt = 0;
    DWORD      ctrlBadMs = 0;       // window before a bad controller field is blamed
    DWORD      walkBadMs = 0;       // window before the handle-walk source is blamed
    DWORD      globalBadMs = 0;     // window before the pawn global source is blamed
    int        waitId = 0;          // 0 = running; tracks wait-state transitions
    bool       announcedActive = false;
    bool       usingScan = false;
    int        chainFails = 0;      // consecutive polls with a failed chain check
    int        fireCount = 0;       // [bhop] diag: hops injected this run
    int        preCount = 0;        // [bhop] diag: speculative pre-jumps fired
    DWORD      airStartMs = 0;      // takeoff tick of the current air time
    DWORD      airDurMs = 0;        // last completed air time (the predictor)
    bool       sawGround = false;   // landed at least once: timing armed
    int        preIdx = 0;          // next pre-jump threshold for this air time
    DWORD      sleepMs = kBhopPollMs; // poll cadence; prediction tightens it

    auto doRelease = [&]() {
        if (!jumpHeld) return;
        if (jumpByMemory && proc) {
            uint32_t nb = 0;
            if (BhopReadT(proc, memBtnAddr, nb))
                BhopWrite32(proc, memBtnAddr, nb & ~bhop::kInJump);
        }
        // Input mode sends nothing here: the pulse already gave the game its
        // edge, and a keyup would poison the OS key state while the physical
        // key is still held (see BhopSendJumpPulse)
        jumpHeld = false;
    };

    // wait state: menu/dead/unspawned is normal game state, never an error —
    // release any injected jump, reset the edge detector, announce once per
    // transition; returns false when the toggle was turned off mid-sleep
    auto waitTick = [&](int id, const char* why) -> bool {
        doRelease();
        prevOnGround = true;
        airStartMs = 0;
        airDurMs = 0;
        sawGround = false;
        spaceHeld = (GetAsyncKeyState(VK_SPACE) & 0x8000) != 0;
        if (waitId != id) {
            waitId = id;
            announcedActive = false;
            BhopStatusf(false, "%s", why);
            Logf("[bhop] %s\n", why);
        }
        return BhopSleep(kBhopPollMs);
    };

    // a spawned pawn must carry an aligned scene node and sane health — a
    // stale freed object reads plausible flags but fails this gate
    auto pawnPlausible = [&](uintptr_t p) -> bool {
        if (!BhopUserPtr(p) || (p & 7)) return false;
        uintptr_t node = 0;
        uint32_t hp = 0;
        return BhopReadT(proc, p + off.sceneNode.cand[off.sceneNode.cur], node) &&
               BhopUserPtr(node) && !(node & 7) &&
               BhopReadT(proc, p + off.health.cand[off.health.cur], hp) && hp <= 250u;
    };

    while (g_bhopEnabled.load()) {
        const DWORD now = GetTickCount();

        // ---- attach ------------------------------------------------------
        if (!proc) {
            const DWORD pid = FindProcessId(L"cs2.exe");
            if (!pid) {
                g_bhopAttached = false;
                BhopStatusf(false, "waiting for cs2.exe");
                if (!BhopSleep(kBhopAttachRetryMs)) break;
                continue;
            }
            // read+write as specified; if the game's integrity level blocks the
            // write handle, fall back to read-only and refuse Memory mode later
            proc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                               PROCESS_QUERY_INFORMATION, FALSE, pid);
            writable = proc != nullptr;
            if (!proc)
                proc = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION,
                                   FALSE, pid);
            if (!proc) {
                BhopStatusf(false, "OpenProcess failed - run as administrator");
                if (!BhopSleep(kBhopAttachRetryMs)) break;
                continue;
            }
            client = ModuleBase(pid, L"client.dll");
            if (!client) {
                CloseHandle(proc);
                proc = nullptr;
                BhopStatusf(false, "waiting for client.dll");
                if (!BhopSleep(kBhopAttachRetryMs)) break;
                continue;
            }
            resolved = false;
            continue;
        }
        if (WaitForSingleObject(proc, 0) == WAIT_OBJECT_0) {
            CloseHandle(proc);
            proc = nullptr;
            g_bhopAttached = false;
            BhopStatusf(false, "cs2.exe exited");
            continue;
        }

        // ---- resolve offsets once per attach -----------------------------
        if (!resolved) {
            std::vector<uint8_t> img;
            if (BhopImageSize(proc, client, imageSize)) {
                img.resize(imageSize);
                if (!BhopRead(proc, client, img.data(), imageSize)) img.clear();
            }
            bool scanned = false;
            if (!BhopResolve(proc, client, imageSize, img, off, scanned)) {
                BhopDisable("offset resolution failed (no scan hit, no fallback)");
                break;
            }
            // unverified signatures can match the wrong global: cross-check the
            // candidates against the live process before trusting any of them
            if (!BhopValidateLive(proc, client, off)) {
                BhopDisable("no plausible candidate (see bhop_offsets.hpp)");
                break;
            }
            if (g_bhopMemoryMode.load() && !writable) {
                BhopDisable("Memory mode needs admin (write access)");
                break;
            }
            resolved = true;
            g_bhopAttached = true;
            prevOnGround = true;
            jumpHeld = false;
            pawnReadFails = 0;
            ctrlBadMs = 0;
            walkBadMs = 0;
            globalBadMs = 0;
            chainFails = 0;
            waitId = 0;
            announcedActive = false;
            usingScan = scanned;
            BhopStatusf(false, "offsets: %s", scanned ? "pattern scan" : "fallback file");
            Logf("[bhop] attached - entityList=0x%llX localPawn=0x%llX controller=0x%llX "
                 "flags=0x%X movSvc=0x%X buttons=0x%X alive=0x%X handle=0x%X (%s)\n",
                 static_cast<unsigned long long>(off.entityList.cand[off.entityList.cur]),
                 static_cast<unsigned long long>(off.localPawn.cand[off.localPawn.cur]),
                 static_cast<unsigned long long>(off.controller.cand[off.controller.cur]),
                 static_cast<unsigned>(off.flags.cand[off.flags.cur]),
                 static_cast<unsigned>(off.moveSvc.cand[off.moveSvc.cur]),
                 static_cast<unsigned>(off.buttons.cand[off.buttons.cur]),
                 static_cast<unsigned>(off.pawnAlive.cand[off.pawnAlive.cur]),
                 static_cast<unsigned>(off.pawnHandle.cand[off.pawnHandle.cur]),
                 scanned ? "scan" : "fallback");
            continue;
        }
        if (g_bhopMemoryMode.load() && !writable) {
            BhopDisable("Memory mode needs admin (write access)");
            break;
        }

        // ---- controller: authoritative game-state gate --------------------
        uintptr_t ctrl = 0;
        if (!BhopReadT(proc, client + off.controller.cand[off.controller.cur], ctrl)) {
            if (++pawnReadFails > 500) {
                BhopDisable("reads failing x%d (process lost?)",
                            pawnReadFails);
                break;
            }
            if (!BhopSleep(kBhopPollMs)) break;
            continue;
        }
        pawnReadFails = 0;
        if (!ctrl) {
            // main menu / not connected — normal, not an error
            if (!waitTick(1, "waiting: not in a match")) break;
            continue;
        }

        // the global must flag itself as THE local controller; a wrong
        // candidate gets a window (uninitialized bytes) before being blamed
        uint8_t isLocal = 0;
        if (BhopUserPtr(ctrl) && !(ctrl & 7) &&
            BhopReadT(proc, ctrl + off.isLocalCtrl.cand[off.isLocalCtrl.cur], isLocal) &&
            isLocal == 1) {
            ctrlBadMs = 0;
        } else {
            ctrlBadMs += kBhopPollMs;
            if (ctrlBadMs >= 5000) {
                ctrlBadMs = 0;
                if (!BhopAdvance(off.controller)) {
                    Logf("[bhop] controller read 0x%llX isLocal=%u\n",
                         static_cast<unsigned long long>(ctrl), isLocal);
                    BhopDisable("stale dwLocalPlayerController (isLocal=%u)", isLocal);
                    break;
                }
                continue;
            }
            if (!waitTick(4, "waiting: controller invalid")) break;
            continue;
        }

        // dead or not spawned: the pawn global holds a stale freed object
        // here (verified live) — wait it out, never validate garbage
        uint8_t alive = 0;
        if (!BhopReadT(proc, ctrl + off.pawnAlive.cand[off.pawnAlive.cur], alive) ||
            alive > 1) {
            // unreadable or not yet initialized: give the field the same
            // window, then treat a sustained bad value as a stale offset
            ctrlBadMs += kBhopPollMs;
            if (ctrlBadMs >= 5000) {
                ctrlBadMs = 0;
                if (!BhopAdvance(off.pawnAlive)) {
                    BhopDisable("stale m_bPawnIsAlive");
                    break;
                }
                continue;
            }
            if (!waitTick(4, "waiting: controller state bad")) break;
            continue;
        }
        ctrlBadMs = 0;
        if (alive != 1) {
            if (!waitTick(2, "dead / not spawned")) break;
            continue;
        }

        // ---- alive: resolve the pawn; two sources, each with its own blame -
        // the controller handle walk is authoritative (it needs a correct
        // entity list) and is the only source used while a handle exists; a
        // source that stays implausible for kBhopRetryMs walks its candidates
        // before the feature gives up. The pawn global only serves as backup
        // when no handle is set.
        uint32_t handle = 0;
        if (!BhopReadT(proc, ctrl + off.pawnHandle.cand[off.pawnHandle.cur], handle)) {
            if (++pawnReadFails > 500) {
                BhopDisable("reads failing x%d (process lost?)",
                            pawnReadFails);
                break;
            }
            if (!BhopSleep(kBhopPollMs)) break;
            continue;
        }
        pawnReadFails = 0;

        uintptr_t pawn = 0;
        if (handle) {
            uintptr_t list = 0;
            if (BhopReadT(proc, client + off.entityList.cand[off.entityList.cur], list) &&
                list) {
                const uintptr_t ent = BhopEntityByIndex(proc, list, handle & 0xFFFF);
                if (ent && pawnPlausible(ent)) pawn = ent;
            }
            if (pawn) {
                walkBadMs = 0;
            } else {
                walkBadMs += kBhopPollMs;
                if (walkBadMs >= kBhopRetryMs) {
                    walkBadMs = 0;
                    // wrong entity list first, then a bogus handle field —
                    // only when both stop offering candidates it is stale
                    if (BhopAdvance(off.entityList)) continue;
                    if (BhopAdvance(off.pawnHandle)) continue;
                    BhopDisable("stale dwEntityList / m_hPlayerPawn (walk fails)");
                    break;
                }
            }
        }

        if (!pawn && handle == 0) {
            uintptr_t g = 0;
            if (!BhopReadT(proc, client + off.localPawn.cand[off.localPawn.cur], g)) {
                if (++pawnReadFails > 500) {
                    BhopDisable("reads failing x%d (process lost?)",
                                pawnReadFails);
                    break;
                }
                if (!BhopSleep(kBhopPollMs)) break;
                continue;
            }
            pawnReadFails = 0;
            if (g && pawnPlausible(g)) {
                pawn = g;
                globalBadMs = 0;
            } else {
                globalBadMs += kBhopPollMs;
                if (globalBadMs >= kBhopRetryMs) {
                    globalBadMs = 0;
                    if (!BhopAdvance(off.localPawn)) {
                        Logf("[bhop] pawn global read 0x%llX implausible\n",
                             static_cast<unsigned long long>(g));
                        BhopDisable("stale dwLocalPlayerPawn (implausible pawn)");
                        break;
                    }
                }
            }
        }

        if (!pawn) {
            // both sources failed this tick — normal mid-spawn; the windows
            // above decide when a candidate is stale, this only waits
            doRelease();
            prevOnGround = true;
            airStartMs = 0;
            airDurMs = 0;
            sawGround = false;
            spaceHeld = (GetAsyncKeyState(VK_SPACE) & 0x8000) != 0;
            if (waitId != 3) {
                waitId = 3;
                announcedActive = false;
                BhopStatusf(false, "waiting: pawn not resolved");
                Logf("[bhop] waiting: alive but pawn not resolved (handle=0x%X)\n", handle);
            }
            if (!BhopSleep(kBhopPollMs)) break;
            continue;
        }

        // ---- chain: flags / movement services / buttons -------------------
        // the pawn passed the plausibility gate, so these reads are meaningful;
        // require persistence before blaming a candidate so a one-tick
        // transition (death, respawn) never advances or disables
        uint32_t flags = 0;
        // real Source fFlags use bits across the whole dword (a live pawn was
        // observed at 0x20010081 — FL_ONGROUND|FL_CLIENT|FL_PARTIALGROUND|bit29),
        // so only zero (not a pawn anymore) and the sign bit (pointer/ASCII
        // garbage tops) are rejected outright; garbage in the middle range is
        // caught by the 200-tick persistence below
        if (!BhopReadT(proc, pawn + off.flags.cand[off.flags.cur], flags) ||
            flags == 0u || flags > 0x7FFFFFFFu) {
            if (++chainFails < kChainFailTicks) {
                if (!BhopSleep(kBhopPollMs)) break;
                continue;
            }
            chainFails = 0;
            if (!BhopAdvance(off.flags)) {
                BhopDisable("stale m_fFlags (read 0x%X)", flags);
                break;
            }
            continue;
        }

        uintptr_t ms = 0;
        if (!BhopReadT(proc, pawn + off.moveSvc.cand[off.moveSvc.cur], ms) ||
            !BhopUserPtr(ms) || (ms & 7)) {
            if (++chainFails < kChainFailTicks) {
                if (!BhopSleep(kBhopPollMs)) break;
                continue;
            }
            chainFails = 0;
            if (!BhopAdvance(off.moveSvc)) {
                BhopDisable("stale m_pMovementServices (0x%llX)",
                            static_cast<unsigned long long>(ms));
                break;
            }
            continue;
        }

        // button bits: IN_* flags stay well under 27 bits (garbage lands as
        // ASCII / pointer halves above it). Only the memory path needs them —
        // Input mode jumps through SendInput and never touches this field, so
        // a client build that lays m_nButtons out elsewhere still gets a
        // working feature (the memory path alone reports the mismatch)
        uint32_t buttons = 0;
        uintptr_t btnAddr = 0;
        if (g_bhopMemoryMode.load()) {
            btnAddr = ms + off.buttons.cand[off.buttons.cur];
            if (!BhopReadT(proc, btnAddr, buttons) || buttons > 0x07FFFFFFu) {
                if (++chainFails < kChainFailTicks) {
                    if (!BhopSleep(kBhopPollMs)) break;
                    continue;
                }
                chainFails = 0;
                if (!BhopAdvance(off.buttons)) {
                    BhopDisable("stale m_nButtons (read 0x%X)", buttons);
                    break;
                }
                continue;
            }
        }

        chainFails = 0;
        if (!announcedActive) {
            waitId = 0;
            announcedActive = true;
            BhopStatusf(false, "active - offsets: %s",
                        usingScan ? "pattern scan" : "fallback file");
            Logf("[bhop] active (spawned, %s)\n", usingScan ? "scan" : "fallback");
        }

        // entity list deep check (every ~200 polls): the chunk behind the
        // global must be a sane pointer whenever it is non-null
        if (now >= checkListAt) {
            checkListAt = now + 200;
            uintptr_t list = 0, chunk = 0;
            if (BhopReadT(proc, client + off.entityList.cand[off.entityList.cur], list) &&
                BhopUserPtr(list) &&
                BhopReadT(proc, list + 0x10, chunk) && chunk != 0 &&
                !BhopUserPtr(chunk)) {
                if (!BhopAdvance(off.entityList)) {
                    BhopDisable("stale dwEntityList (chunk 0x%llX)",
                                static_cast<unsigned long long>(chunk));
                    break;
                }
            }
        }

        // ---- Space-held estimate across our own injected keyups ----------
        const bool rawSpace = (GetAsyncKeyState(VK_SPACE) & 0x8000) != 0;
        if (rawSpace) {
            if (!spaceHeld) Logf("[bhop] space raw down (t=%lu)\n", now);
            spaceHeld = true;
        } else if (static_cast<DWORD>(now - lastOurKeyMs) > kSpaceGraceMs) {
            if (spaceHeld)
                Logf("[bhop] space lost: raw up + grace expired %lu ms after our keyup (t=%lu)\n",
                     now - lastOurKeyMs, now);
            spaceHeld = false;
        }

        // ---- edge trigger: Space held + air->ground = one jump tick ------
        const bool onGround = (flags & bhop::kOnGround) != 0;
        const bool landing   = !prevOnGround && onGround;

        if (jumpHeld && (!onGround || !spaceHeld ||
                         static_cast<int32_t>(now - releaseAt) >= 0)) {
            doRelease();
            Logf("[bhop] release t=%lu flags=0x%X raw=%d reason=%s\n", now, flags,
                 rawSpace ? 1 : 0,
                 !onGround ? "airborne" : (!spaceHeld ? "space lost" : "tick timeout"));
        } else if (!jumpHeld && spaceHeld && landing) {
            // send-time re-check: release can land between the tick-top read
            // and this pulse — a keydown queued behind the physical keyup
            // gets no keyup ahead of it, latching Space down in the async
            // state. rawSpace would then read true forever (our own pulses
            // keep refreshing the grace) and hopping never stops
            if (!(GetAsyncKeyState(VK_SPACE) & 0x8000)) {
                spaceHeld = false;
                Logf("[bhop] fire skipped: space up this tick (t=%lu)\n", now);
            } else {
                if (g_bhopMemoryMode.load()) {
                    if (!BhopWrite32(proc, btnAddr, buttons | bhop::kInJump)) {
                        BhopDisable("WriteProcessMemory failed (%lu) - run as administrator",
                                    GetLastError());
                        break;
                    }
                    memBtnAddr = btnAddr;
                    jumpByMemory = true;
                } else {
                    BhopSendJumpPulse();
                    lastOurKeyMs = GetTickCount();
                    jumpByMemory = false;
                }
                jumpHeld = true;
                releaseAt = now + kBhopTickMs;
                Logf("[bhop] fire #%d t=%lu flags=0x%X raw=%d mode=%s\n",
                     ++fireCount, now, flags, rawSpace ? 1 : 0,
                     jumpByMemory ? "memory" : "input");
            }
        } else if (landing) {
            Logf("[bhop] land, no fire: jumpHeld=%d spaceHeld=%d raw=%d flags=0x%X\n",
                 jumpHeld ? 1 : 0, spaceHeld ? 1 : 0, rawSpace ? 1 : 0, flags);
        }

        // ---- speculative pre-jump: predict THIS touchdown from the last
        // measured air time and put the press inside the landing command's
        // input window — no physics reads, just the previous hop's own
        // duration, which differs only by poll jitter. If the engine checks
        // jump after the move that lands you, that jumps with zero ground
        // ticks; if it checks before, the edge is spent harmlessly in the
        // air and the landing pulse above still fires — never worse than
        // post-landing detection, at worst one wasted mid-air key event
        if (!g_bhopMemoryMode.load()) {
            if (onGround) {
                if (airStartMs) {              // touchdown closes the air time
                    airDurMs = now - airStartMs;   // measured: the next takeoff
                    airStartMs = 0;              // predicts from it
                }
                sawGround = true;
                preIdx = 0;
                sleepMs = kBhopPollMs;
            } else if (sawGround && !airStartMs) {
                airStartMs = now;   // takeoff starts the clock; the sawGround
                                    // arming keeps an enable mid-air from
                                    // recording a partial air time
            } else if (spaceHeld && airDurMs) {
                // predicted touchdown = takeoff + last air time; signed so an
                // overdue prediction keeps firing instead of wrapping huge
                const DWORD landAt = airStartMs + airDurMs;
                const long  tMs = static_cast<long>(landAt - now);
                if (tMs <= 20)
                    sleepMs = 0;    // last stretch: fastest polling, so
                                    // a threshold crossing fires within
                                    // sub-ms instead of up to a poll late
                if (preIdx < kPreN && tMs <= kPreLeads[preIdx] && !jumpHeld) {
                    // same send-time re-check as the fire above: the pre
                    // leads sit inside the grace window, so a pulse after a
                    // genuine release would latch Space down and the loop
                    // would sustain itself on its own pulses
                    if (!(GetAsyncKeyState(VK_SPACE) & 0x8000)) {
                        spaceHeld = false;
                        Logf("[bhop] pre stop: space up this tick (t=%lu)\n", now);
                    } else {
                        BhopSendJumpPulse();
                        lastOurKeyMs = GetTickCount();
                        Logf("[bhop] pre #%d t=%lu air=%lu lead=%ld\n",
                             ++preCount, now, airDurMs, tMs);
                        ++preIdx;
                        while (preIdx < kPreN && tMs <= kPreLeads[preIdx])
                            ++preIdx;   // crossed several in one poll: one
                                        // edge is enough, the rest re-space
                    }
                }
            }
        }

        prevOnGround = onGround;

        if (!BhopSleep(sleepMs)) break;
    }

    doRelease();
    g_bhopAttached = false;
    if (proc) CloseHandle(proc);
    Logf("[bhop] worker stopped\n");
}

static void BhopStop() {
    g_bhopEnabled = false;
    if (g_bhopThread.joinable()) g_bhopThread.join();
}

static void BhopStart() {
    BhopStop();                                // reap a previous auto-disabled run
    {
        std::lock_guard<std::mutex> lock(g_bhopMtx);
        g_bhopError = false;
        g_bhopAttached = false;
        sprintf_s(g_bhopStatus, "starting...");
    }
    g_bhopOn = true;
    g_bhopEnabled = true;
    g_bhopThread = std::thread(BhopWorker);
}

// ---------------------------------------------------------------------------
// radar map art
// ---------------------------------------------------------------------------
// The current map name lives in CGlobalVarsBase as a char* whose slot moves
// between game builds, so RadarMapTick discovers it (MapNameRead) instead
// of trusting a fixed offset. On change the matching art + calibration loads from
// radar/<map>.bmp next to the exe (built by tools/gen_radar.py from the VPK's
// radar textures and overview txts). Art is pre-resampled to the exact size it
// occupies on the minimap, so the per-frame PlgBlt only rotates it ~1:1.
static char     g_radarMap[64]{};      // last accepted map name
static bool     g_radarMapSet = false; // g_radarMap holds a valid read
static HDC      g_artDc[2]{};          // [0] upper art, [1] lower-level art
static HBITMAP  g_artBmp[2]{};
static HGDIOBJ  g_artOld[2]{};
static int      g_artW = 0, g_artH = 0;
static const RadarCal* g_artCal = nullptr;
static DWORD    g_mapCheckMs = 0;

static const RadarCal* FindRadarCal(const char* name) {
    for (const RadarCal& c : kRadarCals)
        if (strcmp(c.name, name) == 0) return &c;
    return nullptr;
}

static void FreeRadarArt() {
    for (int i = 0; i < 2; i++) {
        if (g_artDc[i]) {
            SelectObject(g_artDc[i], g_artOld[i]);
            DeleteDC(g_artDc[i]);
            DeleteObject(g_artBmp[i]);
            g_artDc[i] = nullptr;
            g_artBmp[i] = nullptr;
            g_artOld[i] = nullptr;
        }
    }
    g_artW = g_artH = 0;
    g_artCal = nullptr;
}

// radar\<file>.bmp next to the exe — resolved from the module path, not the
// cwd, so the art is found however the process was started
static bool LoadRadarArt(const char* file, int slot) {
    static char dir[MAX_PATH]{};
    if (!dir[0]) {
        const DWORD n = GetModuleFileNameA(nullptr, dir, MAX_PATH);
        char* slash = (n && n < MAX_PATH) ? strrchr(dir, '\\') : nullptr;
        if (!slash) return false;
        slash[1] = '\0';
    }
    char path[MAX_PATH];
    _snprintf_s(path, _TRUNCATE, "%sradar\\%s.bmp", dir, file);

    HANDLE hf = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, nullptr,
                            OPEN_EXISTING, 0, nullptr);
    if (hf == INVALID_HANDLE_VALUE) return false;
    LARGE_INTEGER sz{};
    GetFileSizeEx(hf, &sz);
    if (sz.QuadPart < 54 || sz.QuadPart > 16 * 1024 * 1024) {
        CloseHandle(hf);
        return false;
    }
    std::vector<unsigned char> bytes(static_cast<size_t>(sz.QuadPart));
    DWORD rd = 0;
    const BOOL ok = ReadFile(hf, bytes.data(), static_cast<DWORD>(bytes.size()),
                             &rd, nullptr);
    CloseHandle(hf);
    if (!ok || rd != bytes.size()) return false;
    if (bytes[0] != 'B' || bytes[1] != 'M') return false;

    auto rd32 = [&](size_t o) { int v; memcpy(&v, &bytes[o], 4); return v; };
    auto rd16 = [&](size_t o) { unsigned short v; memcpy(&v, &bytes[o], 2); return v; };
    const unsigned off = static_cast<unsigned>(rd32(10));
    const int w    = rd32(18);
    const int h    = rd32(22);
    const unsigned bpp  = rd16(28);
    const unsigned comp = static_cast<unsigned>(rd32(30));
    if (bpp != 24 || comp != 0 || w <= 0 || h == 0) return false;
    const long long h64  = h < 0 ? -static_cast<long long>(h) : h;
    if (h64 > 16 * 1024 * 1024) return false;
    const bool   topDown = h < 0;
    const int    height  = static_cast<int>(h64);
    const unsigned stride = (static_cast<unsigned>(w) * 3u + 3u) & ~3u;
    if (off > bytes.size() ||
        static_cast<size_t>(stride) * height > bytes.size() - off) return false;

    BITMAPINFO bi{};
    bi.bmiHeader.biSize        = sizeof(BITMAPINFOHEADER);
    bi.bmiHeader.biWidth       = w;
    bi.bmiHeader.biHeight      = -height;   // top-down DIB
    bi.bmiHeader.biPlanes      = 1;
    bi.bmiHeader.biBitCount    = 24;
    bi.bmiHeader.biCompression = BI_RGB;
    void* dstBits = nullptr;
    HBITMAP bmp = CreateDIBSection(nullptr, &bi, DIB_RGB_COLORS, &dstBits,
                                   nullptr, 0);
    if (!bmp || !dstBits) {
        if (bmp) DeleteObject(bmp);
        return false;
    }
    for (int y = 0; y < height; y++) {          // normalise to top-down rows
        const int srcRow = topDown ? y : (height - 1 - y);
        memcpy(static_cast<unsigned char*>(dstBits) +
                   static_cast<size_t>(y) * stride,
               bytes.data() + off + static_cast<size_t>(srcRow) * stride,
               static_cast<size_t>(w) * 3u);
    }
    HDC dc = CreateCompatibleDC(nullptr);
    if (!dc) {
        DeleteObject(bmp);
        return false;
    }
    if (g_artDc[slot]) {                        // replace a previous image
        SelectObject(g_artDc[slot], g_artOld[slot]);
        DeleteDC(g_artDc[slot]);
        DeleteObject(g_artBmp[slot]);
    }
    g_artOld[slot] = SelectObject(dc, bmp);
    g_artDc[slot]  = dc;
    g_artBmp[slot] = bmp;
    g_artW = w;
    g_artH = height;
    return true;
}

// The map name lives somewhere in CGlobalVarsBase as a char*, but its slot
// moves between game builds (the old hard 0x188 read empty after an
// update, leaving the radar dots-only over the game's own radar). So the
// slot is discovered, not assumed: pointer slots are scanned for a string
// that EXACTLY names a calibrated map, and only that strict match is ever
// accepted. Read-only probing; a miss just leaves dots-only plus a log.
static std::ptrdiff_t g_mapNameOff = -1;   // discovered slot, cached per session

static bool MapNameRead(uintptr_t gv, char* out) {
    auto TrySlot = [&](std::ptrdiff_t off, char* dst) -> bool {
        const uintptr_t np =
            Read<uintptr_t>(gv + static_cast<size_t>(off));
        if (np < 0x10000ULL || np > 0x00007FFFFFFFFFFFULL) return false;
        if (!ReadBytes(np, dst, 64)) return false;
        dst[63] = '\0';
        size_t len = 0;
        while (len < 64 && dst[len]) len++;
        if (len < 3 || len > 62) return false;
        for (size_t i = 0; i < len; i++)
            if (dst[i] < 0x20 || dst[i] > 0x7E) return false;
        return true;
    };
    char tmp[64]{};
    if (g_mapNameOff >= 0) {                 // fast path: known slot
        if (TrySlot(g_mapNameOff, tmp)) {
            memcpy(out, tmp, 64);
            return true;
        }
        g_mapNameOff = -1;                   // struct moved: rescan below
    }
    for (std::ptrdiff_t off = 0x80; off <= 0x220; off += 8) {
        if (!TrySlot(off, tmp)) continue;
        const char* leaf = strrchr(tmp, '/');
        leaf = leaf ? leaf + 1 : tmp;
        const char* bs = strrchr(leaf, '\\');
        if (bs) leaf = bs + 1;
        if (FindRadarCal(leaf)) {            // exact calibration hit only
            g_mapNameOff = off;
            memcpy(out, tmp, 64);
            Logf("[radar] map-name slot +0x%X ('%s')\n",
                 static_cast<unsigned>(off), tmp);
            return true;
        }
    }
    return false;
}

// ~5 Hz: read the map name and follow a change with the matching art. Called
// from CollectPlayers (it runs every frame, even down early-return paths).
static void RadarMapTick() {
    if (!g_radarOn || !g_client) return;
    const DWORD now = GetTickCount();
    if (now - g_mapCheckMs < 200) return;
    g_mapCheckMs = now;

    const uintptr_t gv = Read<uintptr_t>(g_client + off::dwGlobalVars);
    if (!gv) return;
    char name[64]{};
    if (!MapNameRead(gv, name)) return;
    const size_t len = strlen(name);
    if (g_radarMapSet && strcmp(name, g_radarMap) == 0) return;   // unchanged

    memcpy(g_radarMap, name, len + 1);
    g_radarMapSet = true;
    FreeRadarArt();

    // workshop maps arrive as "<dir>/<leaf>": calibrate on the leaf
    const char* leaf = strrchr(name, '/');
    leaf = leaf ? leaf + 1 : name;
    const char* bs = strrchr(leaf, '\\');
    if (bs) leaf = bs + 1;

    g_artCal = FindRadarCal(leaf);
    if (!g_artCal) {
        Logf("[radar] map '%s': no calibration, dots only\n", name);
        return;
    }
    if (!LoadRadarArt(g_artCal->name, 0)) {
        Logf("[radar] map '%s': radar\\%s.bmp missing\n",
             name, g_artCal->name);
        g_artCal = nullptr;
        return;
    }
    bool lower = false;
    if (g_artCal->lowerZ < 1e29f) {
        char f[80];
        _snprintf_s(f, _TRUNCATE, "%s_lower", g_artCal->name);
        lower = LoadRadarArt(f, 1);
        if (!lower)
            Logf("[radar] lower art missing for %s, upper stays\n", leaf);
    }
    Logf("[radar] map '%s' art %dx%d scale=%.2f rot=%d lower=%d\n",
         leaf, g_artW, g_artH, g_artCal->scale, g_artCal->rot,
         lower ? 1 : 0);
}

// ---------------------------------------------------------------------------
// view matrix projection
// ---------------------------------------------------------------------------
static bool WorldToScreen(const Vec3& world, Vec3& screen, const float* m) {
    // column-vector layout: w/nx/ny are rows 3/0/1 of the view-projection matrix
    // (w = row 3 · pos; verified empirically against live gameplay — using column 3
    //  instead collapses every projection to screen center)
    const float w = m[12] * world.x + m[13] * world.y + m[14] * world.z + m[15];
    if (w < 0.001f) return false;                      // behind camera
    const float nx = m[0] * world.x + m[1] * world.y + m[2]  * world.z + m[3];
    const float ny = m[4] * world.x + m[5] * world.y + m[6]  * world.z + m[7];
    screen.x = (g_width  * 0.5f) * (1.0f + nx / w);
    screen.y = (g_height * 0.5f) * (1.0f - ny / w);
    return true;
}

// ---------------------------------------------------------------------------
// C4: bomb timer / site / defuse state. The dump carries no bomb fields, so
// six netvars (+ the two button fields for plant detection) resolve once per
// attach through the bhop schema scanner; anything unresolved stays -1 and
// its display stays hidden. The planted bomb is found by scanning entities
// for a ticking candidate (no designer-name offset in the dump) — ticking +
// a 30..45 s timer length + site 0..2 must ALL agree, so a wrong scan match
// cannot promote garbage into a bomb marker.
// ---------------------------------------------------------------------------
static const bhop::NetvarSpec kC4Ticking  = { "m_bBombTicking",      0x400, 0x1800 };
static const bhop::NetvarSpec kC4TimerLen = { "m_flTimerLength",     0x400, 0x1800 };
static const bhop::NetvarSpec kC4Site     = { "m_nBombSite",         0x400, 0x1800 };
static const bhop::NetvarSpec kC4DefLen   = { "m_flDefuseLength",    0x400, 0x1800 };
static const bhop::NetvarSpec kC4DefCount = { "m_flDefuseCountDown", 0x400, 0x1800 };
static const bhop::NetvarSpec kC4Defuser  = { "m_hBombDefuser",      0x400, 0x1800 };
static const bhop::NetvarSpec kC4MoveSvc  = { "m_pMovementServices", 0x400, 0x4000 };
static const bhop::NetvarSpec kC4Buttons  = { "m_nButtons",          0x10,  0x400  };
static constexpr int kC4Def = 49;   // weapon_c4 definition index
static std::ptrdiff_t g_c4Ticking = -1, g_c4TimerLen = -1, g_c4SiteOff = -1,
                      g_c4DefLen = -1, g_c4DefCount = -1, g_c4Defuser = -1,
                      g_c4MoveSvc = -1, g_c4Buttons = -1;

// bomb state, refreshed by BombTick (~4 Hz)
static int   s_bombIdx = -1;          // cached planted-C4 entity index
static bool  s_bombTicking = false;
static int   s_bombSite = -1;
static float s_bombTimerLen = 40.0f;
static DWORD s_bombPlantMs = 0;       // local time of the observed 0->1 edge
static bool  s_bombSynced = false;    // edge seen this arming: timer is exact
static Vec3  s_bombOrg{};
static bool  s_bombOrgOk = false;
static int   s_defuserIdx = -1;       // entity index of the player defusing (-1 = none)
static DWORD s_defuseStartMs = 0;     // local time of the defuse 0->1 edge
static bool  s_defuseSynced = false;   // edge seen: edge-timestamp countdown exact
static float s_defuseLeft = 0.0f;
static DWORD s_bombMs = 0;            // scan throttle
static float s_defuseLen = 5.0f;        // kit/no-kit defuse length, read live
static DWORD s_plantMs[65] = {};      // USE-held-since per slot (planting needs 300 ms steady)
static uint16_t s_lastWdef[65] = {};  // last logged weapon def per slot (chain diagnostics)
static bool  s_someonePlanting = false;  // any pawn planting this frame (any team)
static char  s_plantName[64] = "";       // ...and their controller name

static void C4Resolve() {
    size_t imageSize = 0;
    std::vector<uint8_t> img;
    if (BhopImageSize(g_process, g_client, imageSize)) {
        img.resize(imageSize);
        if (!BhopRead(g_process, g_client, img.data(), imageSize)) img.clear();
    }
    auto one = [&](const char* label, const bhop::NetvarSpec& spec, std::ptrdiff_t& out) {
        out = -1;
        std::ptrdiff_t found = 0;
        if (!img.empty() && BhopScanNetvar(img, g_client, spec, found)) out = found;
        if (out >= 0) Logf("[c4] %-12s 0x%X\n", label, static_cast<unsigned>(out));
        else          Logf("[c4] %-12s MISSING\n", label);
    };
    one("ticking", kC4Ticking, g_c4Ticking);
    one("timerlen", kC4TimerLen, g_c4TimerLen);
    one("site", kC4Site, g_c4SiteOff);
    one("deflen", kC4DefLen, g_c4DefLen);
    one("defcount", kC4DefCount, g_c4DefCount);
    one("defuser", kC4Defuser, g_c4Defuser);
    one("movesvc", kC4MoveSvc, g_c4MoveSvc);
    one("buttons", kC4Buttons, g_c4Buttons);
    static const bhop::NetvarSpec kFlagsSpec = { "m_fFlags", 0x200, 0x4000 };
    {
        std::ptrdiff_t found = 0;
        g_flagsOff = -1;
        if (!img.empty() && BhopScanNetvar(img, g_client, kFlagsSpec, found)) {
            g_flagsOff = found;
            Logf("[c4] %-12s 0x%X%s\n", "flags", static_cast<unsigned>(found),
                 found == bhop::kFallback.flags ? " (matches bhop fallback)" : "");
        } else {
            Logf("[c4] %-12s MISSING\n", "flags");
        }
    }
}

// ---------------------------------------------------------------------------
// bomb state, refreshed here at ~4 Hz (netvar story in the C4 block above)
// ---------------------------------------------------------------------------
static void BombTick(uintptr_t entityList) {
    const DWORD now = GetTickCount();
    if (now - s_bombMs < 250) return;
    s_bombMs = now;
    if (g_c4Ticking < 0 || g_c4TimerLen < 0 || g_c4SiteOff < 0) return;  // unresolved
    if (s_bombIdx >= 0) {
        const uintptr_t e = EntityByIndex(entityList, static_cast<uint32_t>(s_bombIdx));
        bool tick = false;
        if (e) tick = Read<bool>(e + g_c4Ticking);
        if (!e || !tick) {
            if (s_bombTicking) Logf("[c4] bomb gone (idx=%d)\n", s_bombIdx);
            s_bombIdx = -1; s_bombTicking = false; s_bombSynced = false;
            s_defuserIdx = -1; s_bombOrgOk = false; s_defuseSynced = false;
            return;
        }
        s_bombTimerLen = Read<float>(e + g_c4TimerLen);
        if (g_c4DefLen >= 0) s_defuseLen = Read<float>(e + g_c4DefLen);
        s_bombSite = Read<int>(e + g_c4SiteOff);
        // the slot can be recycled by a non-bomb entity (stale ticking bit) —
        // re-check the conjunction or a phantom bomb sticks forever
        if (s_bombTimerLen < 30.0f || s_bombTimerLen > 45.0f ||
            s_bombSite < 0 || s_bombSite > 2) {
            Logf("[c4] bomb slot recycled (idx=%d) - dropping\n", s_bombIdx);
            s_bombIdx = -1; s_bombTicking = false; s_bombSynced = false;
            s_defuserIdx = -1; s_bombOrgOk = false; s_defuseSynced = false;
            return;
        }
        const uintptr_t node = Read<uintptr_t>(e + net::C_BaseEntity::m_pGameSceneNode);
        if (node) {
            s_bombOrg = Read<Vec3>(node + net::CGameSceneNode::m_vecAbsOrigin);
            s_bombOrgOk = true;
        }
        uint32_t dhRaw = 0;
        if (g_c4Defuser >= 0 && g_c4DefCount >= 0) {
            dhRaw = Read<uint32_t>(e + g_c4Defuser);
            // entity index lives in the low 15 bits (upper bits are serial —
            // masking 16 kept a serial bit and rejected real defusers)
            const int di = static_cast<int>(dhRaw & 0x7FFF);
            if (dhRaw && di > 0 && di < 2048 &&
                EntityByIndex(entityList, static_cast<uint32_t>(di))) {
                if (s_defuserIdx != di) {
                    s_defuserIdx = di;
                    s_defuseStartMs = now;
                    s_defuseSynced = true;
                    Logf("[c4] defuser idx=%d\n", di);
                }
                s_defuseLeft = Read<float>(e + g_c4DefCount);
            } else {
                s_defuserIdx = -1;
                s_defuseSynced = false;
            }
        }
        // defuser buttons cross-check: a live defuse holds USE, so these bits
        // validate the buttons offset the planting tag relies on
        uint32_t dbgDefBtn = 0;
        if (s_defuserIdx >= 0 && g_c4MoveSvc >= 0 && g_c4Buttons >= 0) {
            const uintptr_t dp = EntityByIndex(entityList, static_cast<uint32_t>(s_defuserIdx));
            if (dp) {
                const uintptr_t dms = Read<uintptr_t>(dp + g_c4MoveSvc);
                if (dms > 0x10000ULL && dms < 0x00007FFFFFFFFFFFULL) {
                    const uint32_t db = Read<uint32_t>(dms + g_c4Buttons);
                    if (db <= 0x07FFFFFFu) dbgDefBtn = db;
                }
            }
        }
        // movesvc probe: while a real defuse runs, dump the struct so the
        // true buttons dword can be identified offline (bit 5 held steady)
        {
            static DWORD s_probeMs = 0;
            if (s_defuserIdx >= 0 && now - s_probeMs > 3000) {
                s_probeMs = now;
                const uintptr_t dp = EntityByIndex(entityList, static_cast<uint32_t>(s_defuserIdx));
                const uintptr_t dms = (dp && g_c4MoveSvc >= 0)
                    ? Read<uintptr_t>(dp + g_c4MoveSvc) : 0;
                if (dms > 0x10000ULL && dms < 0x00007FFFFFFFFFFFULL) {
                    uint32_t words[128];
                    if (ReadBytes(dms, words, sizeof(words))) {
                        char line[1400];
                        int o = sprintf_s(line, "[c4] probe");
                        for (int wi = 0; wi < 128 && o > 0 && o < 1300; ++wi)
                            o += sprintf_s(line + o, sizeof(line) - o, " %X", words[wi]);
                        if (o > 0) Logf("%s\n", line);
                    }
                }
            }
        }
        {
            static DWORD s_defdbgMs = 0;   // 1 Hz: raw defuser handle + countdown
            if (now - s_defdbgMs > 1000) {
                s_defdbgMs = now;
                Logf("[c4] tick def=0x%X idx=%d left=%.1f defbtn=0x%X\n",
                     dhRaw, s_defuserIdx, s_defuseLeft, dbgDefBtn);
            }
        }
        return;
    }
    for (int i = 65; i < 2048; ++i) {
        const uintptr_t e = EntityByIndex(entityList, static_cast<uint32_t>(i));
        if (!e) continue;
        if (!Read<bool>(e + g_c4Ticking)) continue;
        const float tl = Read<float>(e + g_c4TimerLen);
        const int site = Read<int>(e + g_c4SiteOff);
        if (tl < 30.0f || tl > 45.0f || site < 0 || site > 2) continue;  // not a bomb
        s_bombIdx = i; s_bombTicking = true;
        s_bombTimerLen = tl; s_bombSite = site;
        s_bombPlantMs = now; s_bombSynced = true;
        s_defuserIdx = -1; s_bombOrgOk = false;
        Logf("[c4] bomb idx=%d site=%d timer=%.1f\n", i, site, tl);
        break;
    }
}

// ---------------------------------------------------------------------------
// one pawn's C4+USE test for the planting tag (the walk and the local check
// share it): C4 in hands (def 49) + USE held steady 300 ms, which kills
// single-frame garbage-bit flicker. The weapon chain mirrors the local one;
// the button offsets resolve per attach and read back range-checked.
static bool PlantHeld(uintptr_t entityList, uintptr_t pawn, int slot,
                      uint32_t& btnOut, uint16_t& defOut) {
    btnOut = 0; defOut = 0;
    if (!pawn || slot < 0 || slot > 64) return false;
    if (s_bombTicking || g_c4MoveSvc < 0 || g_c4Buttons < 0) return false;
    const uintptr_t pws = Read<uintptr_t>(pawn + net::C_BasePlayerPawn::m_pWeaponServices);
    if (!pws) return false;
    const uint32_t wh = Read<uint32_t>(pws + net::CPlayer_WeaponServices::m_hActiveWeapon);
    const uintptr_t wpn = wh ? EntityByIndex(entityList, wh & 0xFFFF) : 0;
    if (wpn) {
        const uintptr_t ctr = wpn + net::C_EconEntity::m_AttributeManager;
        defOut = Read<uint16_t>(ctr + net::C_AttributeContainer::m_Item
                                + net::C_EconItemView::m_iItemDefinitionIndex);
    }
    if (defOut != kC4Def) { s_plantMs[slot] = 0; return false; }
    const uintptr_t ms = Read<uintptr_t>(pawn + g_c4MoveSvc);
    if (ms <= 0x10000ULL || ms >= 0x00007FFFFFFFFFFFULL) return false;
    btnOut = Read<uint32_t>(ms + g_c4Buttons);
    if (btnOut > 0x07FFFFFFu) return false;
    if (btnOut & 32u) {
        if (!s_plantMs[slot]) s_plantMs[slot] = GetTickCount();
        return (GetTickCount() - s_plantMs[slot] >= 300);
    }
    s_plantMs[slot] = 0;
    return false;
}

// ---------------------------------------------------------------------------
// grenade helper: projectile tracking, landing prediction, damage + flash
// estimates
// ---------------------------------------------------------------------------
// Live grenades are found by walking the entity list in bulk (one read per
// 512-slot chunk) and classifying each slot through its CEntityIdentity
// designer name — that offset schema-scans on first use the way the C4 block
// does, and a slot is only promoted after the name string validates and
// matches a known grenade, so a wrong offset can never turn garbage into a
// marker. Flight is extrapolated from a finite-difference velocity under
// sv_gravity onto an estimated floor (lowest player near the arc, yours if
// none); detonations become short-lived result markers. Every number here is
// an approximation — the game keeps its collision traces to itself — and the
// footer of the section says so.
// ---------------------------------------------------------------------------

static bool g_grEspOn = false;   // markers: type, fuse countdown, thrower
static bool g_grPathOn  = false; // trail + predicted landing + blast radius
static bool g_grDmgOn   = false; // HE/fire damage in & out estimates
static bool g_grFlashOn = false; // flashbang blind percentages
static bool g_grEnemyOn = false; // hide grenades thrown by your own team
static int   g_grDist   = 100;   // draw distance, metres
static constexpr int kGrDistMin = 10, kGrDistMax = 250;

enum { kGrenHe = 0, kGrenFlash, kGrenSmoke, kGrenMolotov, kGrenDecoy,
       kGrenFire, kGrenCount };
static const char*    kGrenName[kGrenCount] = { "HE", "FLASH", "SMOKE",
                                                "MOLLY", "DECOY", "FIRE" };
static const COLORREF kGrenCol[kGrenCount] = {
    RGB(255, 92, 92), RGB(240, 220, 96), RGB(110, 200, 255),
    RGB(255, 150, 64), RGB(128, 224, 144), RGB(255, 120, 48) };
// life after first sight: HE/flash fuse at ~1.6 s, the smoke row counts the
// full cloud, the molotov its air fuse, the decoy its life, the fire its burn
static constexpr float kGrenFuse[kGrenCount] = { 1.6f, 1.6f, 18.5f,
                                                 2.0f, 15.0f, 7.0f };
static constexpr float kGrenGrav   = 800.0f;  // sv_gravity for the extrapolation
static constexpr float kHeRadius   = 350.0f;  // HE falloff radius, units
static constexpr float kHeMaxDmg   = 99.0f;   // raw damage at the blast center
static constexpr float kHeArmor    = 0.575f;  // kevlar share (99 raw -> 57 armored)
static constexpr float kFireRadius = 130.0f;  // inferno footprint radius
static constexpr float kFireDps    = 40.0f;   // peak burn damage per second
static constexpr float kFlashFullU = 1300.0f; // distance the full blind holds
static constexpr float kFlashZeroU = 2300.0f; // range where the blind reaches zero
static constexpr int   kGrenMax    = 16;      // tracked slots (live + fading markers)
static constexpr DWORD kGrenEvMs   = 5000;    // result-marker lifetime, ms
static constexpr int   kGrenTrailN = 16;      // path history points per grenade
static constexpr DWORD kGrenScanMs = 25;      // track/scan cadence, ms

// schema-scanned offsets (stay -1 when a scan misses; features degrade)
static std::ptrdiff_t g_grenDesigner = -1;  // CEntityIdentity::m_designerName
static std::ptrdiff_t g_grenThrower  = -1;  // C_CSGrenadeProjectile::m_hThrower
static std::ptrdiff_t g_grenEyeAng   = -1;  // C_CSPlayerPawn::m_angEyeAngles
static std::ptrdiff_t g_grenFlashDur = -1;  // C_CSPlayerPawn::m_flFlashDuration

struct GrenSlot {
    bool  used = false;      // slot occupied (live, or a result still fading)
    bool  live = false;      // entity currently exists
    int   idx  = -1;         // entity index while live
    int   type = 0;
    Vec3  pos{};             // latest position (or the last one before it vanished)
    Vec3  vel{};             // finite-difference velocity
    Vec3  prev{};
    DWORD prevMs = 0;
    int   samples = 0;       // position samples seen (velocity validity)
    DWORD firstMs = 0, deadMs = 0;
    int   trailN = 0;
    Vec3  trail[kGrenTrailN]{};
    int   team = 0;          // thrower team: 2 T, 3 CT, 0 unknown
    char  thrower[40] = "";
    int   youPct = 0;        // flash: current blind estimate for you
    float youDmg = 0;        // HE: damage dealt to you at detonation
    float topDmg = 0;        // HE: worst enemy estimate + who
    char  topName[40] = "";
    int   topPct = 0;        // flash: worst enemy estimate + who
    char  topFName[40] = "";
};
static GrenSlot  g_gren[kGrenMax];
static bool      g_grenTried = false;   // one schema scan attempt per session
static Vec3      s_grLocalOrg{};        // local feet, last tick (draw reads it)
static bool      s_grLocalOrgOk = false;
static int       s_grLocalTeam = 0;

// designer-name pointers are process-stable strings: cache ptr -> class so a
// later scan is pure bulk reads (a cached non-match is remembered too)
struct GrenCls { uintptr_t ptr; int type; };

// one schema scan for the helper's netvars — locate each field's name string
// in client.dll, then the SchemaClassFieldData whose name* points at it
static void GrenadeResolve() {
    if (g_grenTried) return;
    g_grenTried = true;
    size_t imageSize = 0;
    std::vector<uint8_t> img;
    if (BhopImageSize(g_process, g_client, imageSize)) {
        img.resize(imageSize);
        if (!BhopRead(g_process, g_client, img.data(), imageSize)) img.clear();
    }
    auto one = [&](const char* label, const bhop::NetvarSpec& spec, std::ptrdiff_t& out) {
        out = -1;
        std::ptrdiff_t found = 0;
        if (!img.empty() && BhopScanNetvar(img, g_client, spec, found)) out = found;
        if (out >= 0) Logf("[gren] %-12s 0x%X\n", label, static_cast<unsigned>(out));
        else          Logf("[gren] %-12s MISSING\n", label);
    };
    one("designer",  { "m_designerName", 0x8, 0x68 },   g_grenDesigner);
    one("thrower",   { "m_hThrower", 0x500, 0x1600 },   g_grenThrower);
    one("eyeangles", { "m_angEyeAngles", 0x800, 0x4000 }, g_grenEyeAng);
    one("flashdur",  { "m_flFlashDuration", 0x800, 0x4000 }, g_grenFlashDur);
}

// designer name -> grenade class; a dropped weapon is not a projectile, so
// "_projectile" has to appear (or the burning cloud's "inferno")
static bool GrenNameClass(const char* name, int& typeOut) {
    if (strstr(name, "inferno")) { typeOut = kGrenFire; return true; }
    if (!strstr(name, "projectile")) return false;
    if (strstr(name, "hegrenade"))          typeOut = kGrenHe;
    else if (strstr(name, "flashbang"))      typeOut = kGrenFlash;
    else if (strstr(name, "smokegrenade"))   typeOut = kGrenSmoke;
    else if (strstr(name, "molotov") ||
             strstr(name, "incgrenade"))     typeOut = kGrenMolotov;
    else if (strstr(name, "decoy"))          typeOut = kGrenDecoy;
    else return false;
    return true;
}

static bool GrenPrintable(const char* s) {
    const size_t n = strlen(s);
    if (!n || n > 38) return false;
    for (size_t i = 0; i < n; ++i)
        if (s[i] < 32 || s[i] > 126) return false;
    return true;
}

// thrower handle -> team + name, validated from either side: a controller
// carries the player-name field, a pawn carries the team byte and is then
// matched back to its controller through the pawn handle
static void GrenThrower(uintptr_t entityList, uintptr_t gren, GrenSlot& g) {
    g.thrower[0] = '\0';
    g.team = 0;
    if (g_grenThrower < 0) return;
    const uint32_t h = Read<uint32_t>(gren + g_grenThrower);
    const int idx = static_cast<int>(h & 0x7FFF);
    if (!h || idx <= 0 || idx >= 2048) return;
    const uintptr_t ent = EntityByIndex(entityList, static_cast<uint32_t>(idx));
    if (!ent) return;
    char nm[40] = {};
    if (ReadBytes(ent + net::CBasePlayerController::m_iszPlayerName, nm, sizeof(nm) - 1) &&
        GrenPrintable(nm)) {
        sprintf_s(g.thrower, "%s", nm);
        const uint32_t ph = Read<uint32_t>(ent + net::CCSPlayerController::m_hPlayerPawn);
        const uintptr_t pawn = ph ? EntityByIndex(entityList, ph & 0x7FFF) : 0;
        if (pawn) {
            const uint8_t tm = Read<uint8_t>(pawn + net::C_BaseEntity::m_iTeamNum);
            if (tm == 2 || tm == 3) g.team = tm;
        }
        return;
    }
    // handle pointed at a pawn instead: take the team and find the name by
    // scanning the controllers for the one bound to this pawn
    const uint8_t tm = Read<uint8_t>(ent + net::C_BaseEntity::m_iTeamNum);
    if (tm != 2 && tm != 3) return;
    g.team = tm;
    for (int i = 1; i <= 64; ++i) {
        const uintptr_t c = EntityByIndex(entityList, static_cast<uint32_t>(i));
        if (!c) continue;
        const uint32_t ch = Read<uint32_t>(c + net::CCSPlayerController::m_hPlayerPawn);
        if ((ch & 0x7FFF) != static_cast<uint32_t>(idx)) continue;
        char cn[40] = {};
        if (ReadBytes(c + net::CBasePlayerController::m_iszPlayerName, cn, sizeof(cn) - 1) &&
            GrenPrintable(cn)) sprintf_s(g.thrower, "%s", cn);
        break;
    }
}

// estimated floor for the landing projection: your feet plus any player near
// the arc, lowest wins — grenades cross heights and there is no collision
// trace to ask
static float GrenGroundZ(const Vec3& p) {
    float z = s_grLocalOrgOk ? s_grLocalOrg.z : p.z;
    for (const EspPlayer& e : g_players) {
        if (fabsf(e.org.x - p.x) > 1500.0f || fabsf(e.org.y - p.y) > 1500.0f)
            continue;
        if (e.org.z < z) z = e.org.z;
    }
    return z;
}

// ballistic extrapolation from the current sample: step dt until the arc
// crosses the estimated floor (4 s cap); false when it never does
static bool GrenLand(const GrenSlot& g, Vec3& landOut, float& secOut) {
    if (g.samples < 2) return false;
    Vec3 p = g.pos, v = g.vel;
    if (v.x * v.x + v.y * v.y + v.z * v.z < 2500.0f) {  // resting: already down
        landOut = p; secOut = 0.0f; return true;
    }
    const float ground = GrenGroundZ(p);
    const float dt = 1.0f / 64.0f;
    for (int i = 0; i < 256; ++i) {
        v.z -= kGrenGrav * dt;
        p.x += v.x * dt; p.y += v.y * dt; p.z += v.z * dt;
        if (p.z <= ground) { landOut = p; secOut = i * dt; return true; }
    }
    return false;
}

// HE blast model: 99 raw at the center, linear to zero at 350 u, then the
// kevlar share — the community formula, honest under the word "approximate"
static float GrenHeDmg(const Vec3& blast, const Vec3& targetFeet) {
    const float cx = targetFeet.x - blast.x, cy = targetFeet.y - blast.y,
                cz = targetFeet.z + 36.0f - blast.z;   // chest, not feet
    const float d = sqrtf(cx * cx + cy * cy + cz * cz);
    if (d >= kHeRadius) return 0.0f;
    return kHeMaxDmg * (1.0f - d / kHeRadius) * kHeArmor;
}

// eye angles -> unit view direction (yaw 0 faces +X, positive pitch looks
// down); out-of-range reads return false rather than a wrong vector
static bool GrenViewDir(uintptr_t pawn, Vec3& out) {
    if (g_grenEyeAng < 0 || !pawn) return false;
    const Vec3 a = Read<Vec3>(pawn + g_grenEyeAng);
    if (!(a.x >= -89.5f && a.x <= 89.5f) || !(a.y >= -180.5f && a.y <= 180.5f))
        return false;
    const float pr = a.x * 3.14159265f / 180.0f, yr = a.y * 3.14159265f / 180.0f;
    const float cp = cosf(pr);
    out = { cp * cosf(yr), cp * sinf(yr), -sinf(pr) };
    return true;
}

// blind estimate: the CS angle bands (relative facing) scaled by distance —
// the full effect holds to ~1300 u and fades to nothing by ~2300
static int GrenBlindPct(const Vec3& eye, bool viewKnown, const Vec3& view,
                        const Vec3& flash) {
    const float dx = flash.x - eye.x, dy = flash.y - eye.y, dz = flash.z - eye.z;
    const float d = sqrtf(dx * dx + dy * dy + dz * dz);
    float af;
    if (viewKnown) {
        const float vl = sqrtf(view.x * view.x + view.y * view.y + view.z * view.z);
        float c = (vl > 1e-3f && d > 1.0f)
                      ? (dx * view.x + dy * view.y + dz * view.z) / (d * vl)
                      : 1.0f;
        if (c < -1.0f) c = -1.0f;
        if (c >  1.0f) c =  1.0f;
        const float ang = acosf(c) * 57.29578f;
        af = ang <= 53.0f ? 1.00f : ang <= 72.0f ? 0.70f
           : ang <= 101.0f ? 0.40f : 0.20f;
    } else {
        af = d <= 900.0f ? 1.0f : 0.4f;   // angle unknown: near means looking
    }
    float df = 1.0f;
    if (d > kFlashFullU)
        df = 1.0f - (d - kFlashFullU) / (kFlashZeroU - kFlashFullU);
    if (df < 0.0f) df = 0.0f;
    int pct = static_cast<int>(af * df * 100.0f + 0.5f);
    return pct < 0 ? 0 : (pct > 100 ? 100 : pct);
}

// capture a detonation's results while everyone still stands where they did:
// HE stores taken/given damage, flash stores the worst enemy's blind % —
// the other classes had nothing worth keeping and their slots free up
static void GrenFinalize(uintptr_t entityList, GrenSlot& g, DWORD now) {
    g.live = false;
    g.deadMs = now;
    if (g.type == kGrenHe) {
        g.youDmg = s_grLocalOrgOk ? GrenHeDmg(g.pos, s_grLocalOrg) : 0.0f;
        g.topDmg = 0.0f;
        g.topName[0] = '\0';
        for (const EspPlayer& e : g_players) {
            if (!e.enemy || e.health <= 0) continue;
            const float d = GrenHeDmg(g.pos, e.org);
            if (d > g.topDmg) {
                g.topDmg = d;
                sprintf_s(g.topName, "%s", e.name[0] ? e.name : "enemy");
            }
        }
    } else if (g.type == kGrenFlash) {
        g.topPct = 0;
        g.topFName[0] = '\0';
        for (const EspPlayer& e : g_players) {
            if (!e.enemy || e.health <= 0 || !e.bonesOk) continue;
            const Vec3 eye{ e.headWX, e.headWY, e.headWZ };
            bool vok = false;
            Vec3 vd{};
            const uintptr_t ctrl =
                EntityByIndex(entityList, static_cast<uint32_t>(e.slot));
            if (ctrl) {
                const uint32_t ph =
                    Read<uint32_t>(ctrl + net::CCSPlayerController::m_hPlayerPawn);
                const uintptr_t pawn = ph ? EntityByIndex(entityList, ph & 0x7FFF) : 0;
                vok = pawn && GrenViewDir(pawn, vd);
            }
            const int pct = GrenBlindPct(eye, vok, vd, g.pos);
            if (pct > g.topPct) {
                g.topPct = pct;
                sprintf_s(g.topFName, "%s", e.name[0] ? e.name : "enemy");
            }
        }
    }
    if (g.type != kGrenHe && g.type != kGrenFlash) g.used = false;  // nothing to show
}

// ---------------------------------------------------------------------------
// grenade tick: throttled bulk scan + position/damage bookkeeping. Called
// from the main loop whenever any grenade feature is on; drawing only ever
// reads the caches below.
// ---------------------------------------------------------------------------
static void GrenadeTick() {
    if (!(g_grEspOn || g_grPathOn || g_grDmgOn || g_grFlashOn)) return;
    GrenadeResolve();
    if (g_grenDesigner < 0) return;          // no identity names: no helper
    const DWORD now = GetTickCount();
    static DWORD s_passMs = 0;
    if (now - s_passMs < kGrenScanMs) return;
    s_passMs = now;

    const uintptr_t entityList = Read<uintptr_t>(g_client + off::dwEntityList);
    if (!entityList) return;

    // local reference: feet for distance/ground, team for the enemy filter
    const uintptr_t lp = Read<uintptr_t>(g_client + off::dwLocalPlayerPawn);
    if (lp) {
        const uintptr_t ln = Read<uintptr_t>(lp + net::C_BaseEntity::m_pGameSceneNode);
        if (ln) {
            s_grLocalOrg = Read<Vec3>(ln + net::CGameSceneNode::m_vecAbsOrigin);
            s_grLocalOrgOk = true;
        }
        const uint8_t tm = Read<uint8_t>(lp + net::C_BaseEntity::m_iTeamNum);
        s_grLocalTeam = (tm == 2 || tm == 3) ? tm : 0;
    } else {
        s_grLocalOrgOk = false;
        s_grLocalTeam = 0;
    }

    // ---- position refresh for the slots we already track ------------------
    for (GrenSlot& g : g_gren) {
        if (!g.used || !g.live) continue;
        const uintptr_t e = EntityByIndex(entityList, static_cast<uint32_t>(g.idx));
        if (!e) continue;
        const uintptr_t node = Read<uintptr_t>(e + net::C_BaseEntity::m_pGameSceneNode);
        if (!node) continue;
        const Vec3 p = Read<Vec3>(node + net::CGameSceneNode::m_vecAbsOrigin);
        if (!(p.x > -16384.0f && p.x < 16384.0f)) continue;  // garbage: keep the old one
        if (g.samples) {
            const float dt = (now - g.prevMs) / 1000.0f;
            if (dt > 0.004f && dt < 0.5f) {
                const Vec3 nv{ (p.x - g.prev.x) / dt,
                               (p.y - g.prev.y) / dt,
                               (p.z - g.prev.z) / dt };
                g.vel.x = g.vel.x * 0.5f + nv.x * 0.5f;
                g.vel.y = g.vel.y * 0.5f + nv.y * 0.5f;
                g.vel.z = g.vel.z * 0.5f + nv.z * 0.5f;
                ++g.samples;
            }
        } else {
            g.samples = 1;
        }
        g.prev = p; g.prevMs = now;
        g.pos = p;
        if (!g.trailN) g.trail[g.trailN++] = p;
        else {
            const Vec3& last = g.trail[g.trailN - 1];
            const float dx = p.x - last.x, dy = p.y - last.y, dz = p.z - last.z;
            if (dx * dx + dy * dy + dz * dz > 100.0f) {  // one point per ~10 u
                if (g.trailN < kGrenTrailN) g.trail[g.trailN++] = p;
                else {
                    memmove(&g.trail[0], &g.trail[1], sizeof(Vec3) * (kGrenTrailN - 1));
                    g.trail[kGrenTrailN - 1] = p;
                }
            }
        }
        // flash: keep your own blind estimate fresh while it flies
        if (g.type == kGrenFlash && g_grFlashOn) {
            Vec3 vd{};
            const bool vok = GrenViewDir(lp, vd);
            Vec3 eye = s_grLocalOrg;
            if (lp) {
                const Vec3 vo = Read<Vec3>(lp + net::C_BaseModelEntity::m_vecViewOffset);
                if (vo.z > 16.0f && vo.z < 110.0f) eye.z += vo.z;
            }
            g.youPct = GrenBlindPct(eye, vok, vd, g.pos);
        }
    }

    // ---- bulk scan: classify every slot through its designer name ---------
    static GrenCls s_cls[128];
    static int     s_clsN = 0;
    auto classify = [&](uintptr_t namePtr) -> int {
        if (!namePtr) return -1;
        for (int i = 0; i < s_clsN; ++i)
            if (s_cls[i].ptr == namePtr) return s_cls[i].type;
        char nm[64] = {};
        int type = 0;
        int res = -1;
        if (ReadBytes(namePtr, nm, sizeof(nm) - 1) && GrenPrintable(nm) &&
            GrenNameClass(nm, type)) {
            res = type;
            Logf("[gren] class \"%s\" -> %s\n", nm, kGrenName[type]);
        }
        if (s_clsN < 128) s_cls[s_clsN++] = { namePtr, res };
        return res;
    };

    bool seen[kGrenMax] = {};
    static uint8_t s_chunkBuf[0xE000];      // 512 identity slots x 0x70
    for (int c = 0; c < 4; ++c) {           // entity indices 1..2047
        const uintptr_t chunk = Read<uintptr_t>(entityList + 0x10 + 8ULL * c);
        if (!chunk) continue;
        if (!ReadBytes(chunk, s_chunkBuf, sizeof(s_chunkBuf))) continue;
        for (int s = 0; s < 512; ++s) {
            const uint32_t idx = static_cast<uint32_t>(c * 512 + s);
            if (idx == 0) continue;
            const uintptr_t ent = *reinterpret_cast<uintptr_t*>(s_chunkBuf + s * 0x70);
            if (!ent) continue;
            const uintptr_t namePtr = *reinterpret_cast<uintptr_t*>(
                s_chunkBuf + s * 0x70 + g_grenDesigner);
            const int type = classify(namePtr);
            if (type < 0) continue;

            GrenSlot* slot = nullptr;
            int si = -1;
            for (int i = 0; i < kGrenMax; ++i)
                if (g_gren[i].used && g_gren[i].live &&
                    g_gren[i].idx == static_cast<int>(idx)) { si = i; break; }
            if (si < 0) {
                for (int i = 0; i < kGrenMax; ++i)
                    if (!g_gren[i].used) { si = i; break; }
                if (si < 0) {              // full: reclaim the oldest finished marker
                    int old = -1;
                    for (int i = 0; i < kGrenMax; ++i) {
                        GrenSlot& r = g_gren[i];
                        if (r.live || !r.deadMs) continue;
                        if (old < 0 || r.deadMs < g_gren[old].deadMs) old = i;
                    }
                    if (old >= 0 && now - g_gren[old].deadMs > kGrenEvMs) si = old;
                }
                if (si < 0) continue;      // everything is busy: drop this one
                GrenSlot& n = g_gren[si];
                n = GrenSlot{};
                n.used = true; n.live = true;
                n.idx = static_cast<int>(idx);
                n.type = type;
                n.prevMs = now;
                n.firstMs = now;
                GrenThrower(entityList, ent, n);
                Logf("[gren] track idx=%d %s by %s\n", idx, kGrenName[type],
                     n.thrower[0] ? n.thrower : "?");
            }
            seen[si] = true;
        }
    }

    // ---- vanished since the last pass: a detonation, or the cloud out -----
    for (int i = 0; i < kGrenMax; ++i) {
        GrenSlot& g = g_gren[i];
        if (g.used && g.live && !seen[i]) GrenFinalize(entityList, g, now);
    }
    // ---- expire finished result markers ----------------------------------
    for (GrenSlot& g : g_gren)
        if (g.used && !g.live && now - g.deadMs > kGrenEvMs) g.used = false;
}

// per-frame player collection
// ---------------------------------------------------------------------------
static float g_vmCur[16] = {};        // latest view matrix (lead sampler)

// ---- bullet tracers ---------------------------------------------------------
// Watch each controller's pawn for a jump in m_iShotsFired — a jump means a
// shot: record the eye position and eye-angle direction, and the draw pass
// renders it as a short fading streak. Its own controller walk and matrix
// read keep tracers alive with every other feature (and the wallhack
// master) off; the walk throttles to every ~8 ms, still far tighter than
// the fastest fire rate, and a counter jump accumulates between samples
struct TracerShot {
    Vec3  eye;           // world muzzle position when the shot fired
    Vec3  dir;           // unit view direction at that moment
    DWORD born;          // GetTickCount() — drives the fade
    unsigned char src;   // 0 enemy, 1 local, 2 teammate
};
static constexpr int   kTrcMax    = 64;       // ring buffer slots
static constexpr int   kTrcLifeMin = 100, kTrcLifeMax = 3000;   // duration slider range, ms
static constexpr float kTrcThkMin = 1.0f, kTrcThkMax = 6.0f;    // thickness slider range, design px
static constexpr float kTrcSpeed  = 6.0f;      // streak speed along the path, units per ms
static constexpr float kTrcTrail   = 250.0f;    // streak length along the path, units
static constexpr float kTrcShrink  = 0.5f;      // share of the life spent shrinking away
static constexpr float kTrcMuzR    = 8.0f;      // muzzle offset from the eye: right, down,
static constexpr float kTrcMuzD    = 7.0f;      // forward — the streak starts at the gun
static constexpr float kTrcMuzF    = 20.0f;
static TracerShot g_trc[kTrcMax];
static int        g_trcNext = 0;
static void TracerTick() {
    if (!(g_trcE || g_trcL || g_trcM)) return;
    static DWORD s_last = 0;
    const DWORD tickNow = GetTickCount();
    if (tickNow - s_last < 8) return;
    s_last = tickNow;

    float vm[16];
    if (ReadBytes(g_client + off::dwViewMatrix, vm, sizeof(vm))) memcpy(g_vmCur, vm, sizeof(vm));
    const uintptr_t entityList = Read<uintptr_t>(g_client + off::dwEntityList);
    if (!entityList) return;
    const uintptr_t localPawn = Read<uintptr_t>(g_client + off::dwLocalPlayerPawn);
    const uint8_t localTeam =
        localPawn ? Read<uint8_t>(localPawn + net::C_BaseEntity::m_iTeamNum) : 0;
    if (localTeam < 2) return;   // menu / spectator: no team to split sides by

    static int       s_prevShots[kMaxPlayers + 1] = {};
    static uintptr_t s_prevPawn[kMaxPlayers + 1] = {};
    for (int i = 1; i <= kMaxPlayers; ++i) {
        const uintptr_t controller = EntityByIndex(entityList, static_cast<uint32_t>(i));
        if (!controller) continue;
        const uint32_t pawnHandle =
            Read<uint32_t>(controller + net::CCSPlayerController::m_hPlayerPawn);
        if (!pawnHandle) continue;
        const uintptr_t pawn = EntityByIndex(entityList, pawnHandle & 0xFFFF);
        if (!pawn) continue;

        const bool isLocal = pawn == localPawn;
        const uint8_t team = Read<uint8_t>(pawn + net::C_BaseEntity::m_iTeamNum);
        const unsigned char src = isLocal ? 1 : (team == localTeam ? 2u : 0u);
        if (!(src == 0 ? g_trcE : src == 1 ? g_trcL : g_trcM)) continue;

        const int shots = Read<int>(pawn + net::C_CSPlayerPawn::m_iShotsFired);
        const int prev  = s_prevShots[i];
        s_prevShots[i] = shots;
        if (pawn != s_prevPawn[i]) { s_prevPawn[i] = pawn; continue; }  // new pawn: baseline only
        if (shots <= prev) continue;   // idle, or the counter reset on death/round

        const uintptr_t node = Read<uintptr_t>(pawn + net::C_BaseEntity::m_pGameSceneNode);
        if (!node) continue;
        const Vec3 org = Read<Vec3>(node + net::CGameSceneNode::m_vecAbsOrigin);
        const Vec3 vo  = Read<Vec3>(pawn + net::C_BaseModelEntity::m_vecViewOffset);
        const Vec3 eye{ org.x, org.y, org.z + vo.z };

        // eye angles -> direction, range-checked like GrenViewDir
        const Vec3 a = Read<Vec3>(pawn + net::C_CSPlayerPawn::m_angEyeAngles);
        if (!(a.x >= -89.5f && a.x <= 89.5f) || !(a.y >= -180.5f && a.y <= 180.5f)) continue;
        const float pr = a.x * 3.14159265f / 180.0f, yr = a.y * 3.14159265f / 180.0f;
        const float cp = cosf(pr);
        const Vec3 dir{ cp * cosf(yr), cp * sinf(yr), -sinf(pr) };

        // muzzle, not the eye: the shooter's right is cross(dir, +z), down is
        // cross(dir, right); the barrel sits right-down-forward of the eye so
        // the streak leaves the gun instead of starting under the crosshair
        Vec3 right{ dir.y, -dir.x, 0.0f };
        const float rl = sqrtf(right.x * right.x + right.y * right.y);
        if (rl > 0.001f) { right.x /= rl; right.y /= rl; } else { right = { 1.0f, 0.0f, 0.0f }; }
        const Vec3 down{ -dir.z * right.y, dir.z * right.x,
                         dir.x * right.y - dir.y * right.x };
        const Vec3 muzzle{ eye.x + right.x * kTrcMuzR + down.x * kTrcMuzD + dir.x * kTrcMuzF,
                           eye.y + right.y * kTrcMuzR + down.y * kTrcMuzD + dir.y * kTrcMuzF,
                           eye.z + right.z * kTrcMuzR + down.z * kTrcMuzD + dir.z * kTrcMuzF };

        TracerShot& t = g_trc[g_trcNext];
        g_trcNext = (g_trcNext + 1) % kTrcMax;
        t = { muzzle, dir, tickNow, src };
    }
}

// screen-space "crosshair lies on this figure" test for the autowall pick:
// the bounding rect of the projected head-feet box, deliberately loose — the
// trigger's silhouette test still validates the exact hit region at fire time
static bool CrosshairOnBox(const EspPlayer& p) {
    const float cx = g_width * 0.5f, cy = g_height * 0.5f;
    const float h  = p.feetY - p.headY;          // figure height, px
    if (h <= 1.0f) return false;                 // degenerate projection
    const float hw = h * 0.35f;                  // half body width
    const float l = (p.headX < p.feetX ? p.headX : p.feetX) - hw;
    const float r = (p.headX > p.feetX ? p.headX : p.feetX) + hw;
    return cx >= l && cx <= r && cy >= p.headY && cy <= p.feetY;
}

static std::vector<EspPlayer> CollectPlayers() {
    RadarMapTick();   // follow the loaded map with the radar art (throttled)
    std::vector<EspPlayer> out;
    g_trigCond = false;   // re-derived from this frame's crosshair trace below
    g_trigPawn = 0;
    g_trigVisible = false;
    g_trigSkelOk = false; // ...with the target's skeleton, health and distance
    g_idEntSlot = -1; g_idEntPawn = 0;   // ...and the crosshair trace below
    g_trigAw = false; g_awSlot = -1; // ...and the autowall pick below
    s_someonePlanting = false;   // re-derived in the walk below (any team)
    s_plantName[0] = '\0';
    int trigSlot = -1;    // slot of the trigger target, matched during the walk
    g_radarValid = false; // re-captured below; stays false on every early return

    float vm[16];
    if (!ReadBytes(g_client + off::dwViewMatrix, vm, sizeof(vm))) {
        Logf("[collect] early: viewmatrix read failed\n");
        return out;
    }
    memcpy(g_vmCur, vm, sizeof(vm));   // current matrix for the lead sampler

    const uintptr_t localPawn = Read<uintptr_t>(g_client + off::dwLocalPlayerPawn);
    if (!localPawn) { Logf("[collect] early: no local pawn (menu?)\n"); return out; }
    const uint8_t localTeam = Read<uint8_t>(localPawn + net::C_BaseEntity::m_iTeamNum);
    if (localTeam < 2) { Logf("[collect] early: local team=%u\n", localTeam); return out; }

    // radar: the local origin centres the map; the local eye anchors the
    // forward-sign test in DrawRadar (three reads, radar only)
    if (g_radarOn) {
        const uintptr_t lnode =
            Read<uintptr_t>(localPawn + net::C_BaseEntity::m_pGameSceneNode);
        if (lnode) {
            g_radarPos = Read<Vec3>(lnode + net::CGameSceneNode::m_vecAbsOrigin);
            const Vec3 vo = Read<Vec3>(localPawn + net::C_BaseModelEntity::m_vecViewOffset);
            g_radarEye  = { g_radarPos.x, g_radarPos.y, g_radarPos.z + vo.z };
            g_radarValid = true;
        }
    }

    const uintptr_t entityList = Read<uintptr_t>(g_client + off::dwEntityList);
    if (!entityList) { Logf("[collect] early: no entity list\n"); return out; }
    BombTick(entityList);   // planted-C4 state for the timer/site/defuse display

    // buttons-offset self-validation: correlate the local movement-services
    // struct against physically held SPACE (ground truth for IN_JUMP). Runs
    // at 2 Hz while playing; offsets tracking the jump bit both ways report
    // every 30 s — the winner is the true m_nButtons for the planting tag.
    {
        static DWORD s_bpMs = 0, s_bpLogMs = 0;
        static int s_held[128], s_heldBit[128], s_free[128], s_freeBit[128];
        const DWORD bpNow = GetTickCount();
        if (!g_menuOpen && localPawn && bpNow - s_bpMs >= 500) {
            s_bpMs = bpNow;
            const int lhp = Read<int>(localPawn + net::C_BaseEntity::m_iHealth);
            if (lhp > 0 && lhp <= 100 && g_c4MoveSvc >= 0) {
                const uintptr_t lms = Read<uintptr_t>(localPawn + g_c4MoveSvc);
                if (lms > 0x10000ULL && lms < 0x00007FFFFFFFFFFFULL) {
                    uint32_t w[128];
                    if (ReadBytes(lms, w, sizeof(w))) {
                        const bool space = (GetAsyncKeyState(VK_SPACE) & 0x8000) != 0;
                        for (int k = 0; k < 128; ++k) {
                            if (w[k] > 0x07FFFFFFu) continue;   // pointer/garbage lane
                            if (space) { ++s_held[k]; if (w[k] & 2u) ++s_heldBit[k]; }
                            else       { ++s_free[k]; if (!(w[k] & 2u)) ++s_freeBit[k]; }
                        }
                    }
                }
            }
        }
        if (bpNow - s_bpLogMs > 30000) {
            s_bpLogMs = bpNow;
            int lanes = 0;
            for (int k = 0; k < 128; ++k) if (s_held[k] > 0) ++lanes;
            Logf("[c4] btnprobe lanes=%d (held samples seen)\n", lanes);
            for (int k = 0; k < 128; ++k) {
                if (s_held[k] >= 20 && s_heldBit[k] * 10 >= s_held[k] * 9 &&
                    s_free[k] >= 20 && s_freeBit[k] * 10 >= s_free[k] * 9)
                    Logf("[c4] btnprobe OK +0x%X held=%d/%d free=%d/%d\n",
                         k * 4, s_heldBit[k], s_held[k], s_freeBit[k], s_free[k]);
            }
        }
    }

    // local under-crosshair trace target: the game recomputes it every frame
    // with a wall-respecting ray (it drives the player-name HUD), so it reports
    // a peek into the crosshair before the networked spotted mask catches up.
    // Read unconditionally — the hit log attributes damage through this slot
    // and needs it with aim/trigger off (one cheap read per frame otherwise)
    const int idEnt = Read<int>(localPawn + net::C_CSPlayerPawn::m_iIDEntIndex);
    const uintptr_t idEntPawn =
        idEnt > 0 ? EntityByIndex(entityList, static_cast<uint32_t>(idEnt)) : 0;

    // scope state for the sniper gate: m_bIsScoped flips with the zoom level
    g_scoped = (g_triggerOn || g_awOn) &&
               Read<bool>(localPawn + net::C_CSPlayerPawn::m_bIsScoped);
    // flash state for the flash check: any real flash blinds the trigger
    g_trigFlashed = (g_triggerOn || g_awOn) && g_grenFlashDur >= 0 &&
                    Read<float>(localPawn + g_grenFlashDur) > 0.75f;

    // local origin for the trigger's max-distance gate (the radar block above
    // owns its separate copy of this read)
    Vec3 localOrg{};
    bool localOrgOk = false;
    if (g_triggerOn || g_revTg || g_awOn) {
        const uintptr_t lnode =
            Read<uintptr_t>(localPawn + net::C_BaseEntity::m_pGameSceneNode);
        if (lnode) {
            localOrg = Read<Vec3>(lnode + net::CGameSceneNode::m_vecAbsOrigin);
            localOrgOk = true;
        }
    }

    // knife out -> the aimbot idles; active weapon handle -> weapon entity ->
    // econ item view -> definition index (defaults 42/59, skins 500..599)
    static DWORD s_knifeMs   = 0;   // when the current knife streak began
    static bool  s_snipState = false; // stable sniper state (streak below)
    static DWORD s_snipMs    = 0;   // when the current sniper streak began
    static bool  s_revState = false; // stable revolver state (streak below)
    static DWORD s_revMs    = 0;   // when the current revolver streak began
    if (g_aimOn || g_triggerOn || g_forceXh || g_revTg || g_awOn) {
        bool knife  = false;
        bool sniper = false;
        bool revolver = false;
        const uintptr_t weapSvc = Read<uintptr_t>(
            localPawn + net::C_BasePlayerPawn::m_pWeaponServices);
        if (weapSvc) {
            const uint32_t wh = Read<uint32_t>(
                weapSvc + net::CPlayer_WeaponServices::m_hActiveWeapon);
            const uintptr_t weapon = wh ? EntityByIndex(entityList, wh & 0xFFFF) : 0;
            uint16_t def = 0;
            if (weapon) {
                const uintptr_t container =
                    weapon + net::C_EconEntity::m_AttributeManager;
                def = Read<uint16_t>(
                    container + net::C_AttributeContainer::m_Item
                              + net::C_EconItemView::m_iItemDefinitionIndex);
                knife  = (def == 42 || def == 59 || (def >= 500 && def < 600));
                sniper = (def == 9 || def == 11 || def == 38 || def == 40);
                revolver = (def == 64);           // R8 Revolver
            }
            g_wepDef = def;   // 0 when unreadable: the damage gate passes it
        } else {
            g_wepDef = 0;
        }
        // The flicker lives around switches, and it must be filtered
        // asymmetrically: a reticle that lingers over a rifle is what the
        // player notices, so dropping it commits after 30 ms (2 frames — a
        // single bad read while holding does nothing), while picking one up
        // waits out a full 100 ms of stable sniper read. A switch's rapid 1/0
        // flips can never satisfy that, so no flicker-back mid-switch.
        const DWORD need = sniper ? 100 : 30;
        if (sniper != s_snipState) {
            if (!s_snipMs) s_snipMs = GetTickCount();
            if (GetTickCount() - s_snipMs >= need) {
                s_snipState  = sniper;
                g_sniperHeld = sniper;
                s_snipMs     = 0;
                Logf("[weap] sniper=%d t=%lu\n", sniper ? 1 : 0, GetTickCount());
            }
        } else {
            s_snipMs = 0;
        }
        // the revolver trigger reads the same chain: acquire waits out 100 ms
        // of stable read, a drop commits in 30 ms (a swap can never satisfy
        // the acquire streak, so no hold shot starts on the wrong gun)
        const DWORD revNeed = revolver ? 100 : 30;
        if (revolver != s_revState) {
            if (!s_revMs) s_revMs = GetTickCount();
            if (GetTickCount() - s_revMs >= revNeed) {
                s_revState     = revolver;
                g_revolverHeld = revolver;
                s_revMs        = 0;
                Logf("[weap] revolver=%d t=%lu\n", revolver ? 1 : 0, GetTickCount());
            }
        } else {
            s_revMs = 0;
        }
        // the weapon read flickers around switches (same-ms 1/0 flips in the
        // log), so a knife streak must hold 250 ms before it disables the
        // aimbot; a gun read re-enables it in the same iteration
        if (knife) {
            if (!s_knifeMs) s_knifeMs = GetTickCount();
            if (!g_knifeOut && GetTickCount() - s_knifeMs >= 250) {
                g_knifeOut = true;
                Logf("[weap] knife=1 t=%lu\n", GetTickCount());
            }
        } else {
            s_knifeMs = 0;
            if (g_knifeOut) {
                g_knifeOut = false;
                Logf("[weap] knife=0 t=%lu\n", GetTickCount());
            }
        }
    } else {
        g_knifeOut  = false;
        s_knifeMs   = 0;
        s_snipState = false;
        s_snipMs    = 0;
        g_sniperHeld = false;
        g_revolverHeld = false;
        s_revState = false;
        s_revMs    = 0;
        g_wepDef     = 0;
    }

    // resolve (and periodically re-resolve) the local controller's list index —
    // it is the bit position of "me" in every pawn's spotted-by mask
    const uintptr_t localCtl = Read<uintptr_t>(g_client + off::dwLocalPlayerController);
    static uintptr_t s_localCtl = 0;
    static DWORD     s_localMs  = 0;
    static int       s_localIdx = 0;
    if (localCtl && (localCtl != s_localCtl || GetTickCount() - s_localMs > 1000)) {
        s_localCtl = localCtl;
        s_localMs  = GetTickCount();
        s_localIdx = 0;
        for (int i = 1; i <= kMaxPlayers; ++i) {
            if (EntityByIndex(entityList, static_cast<uint32_t>(i)) == localCtl) {
                s_localIdx = i;
                break;
            }
        }
        if (s_localIdx)
            Logf("[vis] local controller idx=%d\n", s_localIdx);
    }

    // last frame each slot's raw visibility signal fired (spotted mask or the
    // under-crosshair trace): both flicker frame to frame, so the state is held
    // for kVisHoldMs after the last positive sample instead of being re-taken
    // from a single frame's bit
    static DWORD s_visMs[kMaxPlayers + 1] = {};

    int nIsLocal = 0, nDead = 0, nNoHandle = 0, nNoPawn = 0, nNoHealth = 0,
        nLife = 0, nTeam = 0, nMate = 0, nNoNode = 0, nDormant = 0,
        nProj = 0, nCull = 0, nOnScr = 0;

    // local planting: the walk below skips our own pawn, so check it directly
    // (slot 0 in the hold/seen tables, never touched by the 1..64 walk)
    if (localPawn) {
        uint32_t lbtn = 0; uint16_t ldef = 0;
        if (PlantHeld(entityList, localPawn, 0, lbtn, ldef) && !s_someonePlanting) {
            s_someonePlanting = true;
            sprintf_s(s_plantName, "(you)");
        }
        if (ldef != s_lastWdef[0]) {
            s_lastWdef[0] = ldef;
            Logf("[c4] slot=0 weap=%d buttons=0x%X (you)\n", ldef, lbtn);
        }
    }

    for (int i = 1; i <= kMaxPlayers; ++i) {
        const uintptr_t controller = EntityByIndex(entityList, static_cast<uint32_t>(i));
        if (!controller) continue;
        if (Read<bool>(controller + net::CBasePlayerController::m_bIsLocalPlayerController)) { ++nIsLocal; continue; }
        if (!Read<bool>(controller + net::CCSPlayerController::m_bPawnIsAlive)) { ++nDead; continue; }

        const uint32_t pawnHandle = Read<uint32_t>(controller + net::CCSPlayerController::m_hPlayerPawn);
        if (!pawnHandle) { ++nNoHandle; continue; }
        const uintptr_t pawn = EntityByIndex(entityList, pawnHandle & 0xFFFF);
        if (!pawn || pawn == localPawn) { ++nNoPawn; continue; }

        const int health = Read<int>(pawn + net::C_BaseEntity::m_iHealth);
        if (health <= 0 || health > 100) { ++nNoHealth; continue; }
        if (Read<uint8_t>(pawn + net::C_BaseEntity::m_lifeState) != 0) { ++nLife; continue; }

        // planting test for this pawn (teammates included — the tag matters
        // whoever plants); weapon changes log so a dead chain is visible
        uint32_t pbtn = 0; uint16_t pdef = 0;
        const bool planting = PlantHeld(entityList, pawn, i, pbtn, pdef);
        if (pdef != s_lastWdef[i]) {
            s_lastWdef[i] = pdef;
            Logf("[c4] slot=%d weap=%d buttons=0x%X\n", i, pdef, pbtn);
        }
        if (planting && !s_someonePlanting) {
            s_someonePlanting = true;
            ReadBytes(controller + net::CBasePlayerController::m_iszPlayerName,
                      s_plantName, sizeof(s_plantName) - 1);
        }

        const uint8_t team = Read<uint8_t>(pawn + net::C_BaseEntity::m_iTeamNum);
        if (team < 2) { ++nTeam; continue; }
        const bool enemy = team != localTeam;
        if (!enemy && !kShowTeammates) { ++nMate; continue; }

        // m_iIDEntIndex may resolve either the pawn or its controller
        // depending on how the ray hit, so both forms count as "this one"
        const bool idEntHit =
            idEntPawn && (idEntPawn == pawn || idEntPawn == controller);

        // triggerbot condition: the game's own per-frame crosshair trace
        // resolved THIS pawn — a live enemy sitting exactly under the sights,
        // with the game's own wall check already applied to the ray. The box
        // is captured below, once this pawn has been projected.
        if ((g_triggerOn || g_revTg) && enemy && idEntHit) {
            trigSlot = i;
            g_trigAw = false;   // visible-ray pick: the trigger's own rules apply
            g_awSlot = -1;
        }
        if (idEntHit) { g_idEntSlot = i; g_idEntPawn = pawn; }

        const uintptr_t sceneNode = Read<uintptr_t>(pawn + net::C_BaseEntity::m_pGameSceneNode);
        if (!sceneNode) { ++nNoNode; continue; }
        if (Read<bool>(sceneNode + net::CGameSceneNode::m_bDormant)) { ++nDormant; continue; }

        // line of sight: the pawn's spotted-by mask, bit for the local player's
        // controller slot — set by the game while that pawn is actually visible
        // to us, so a pawn behind a wall is not selected (the mask/trace both
        // flicker frame to frame, hence the s_visMs latch below)
        bool visible = false;
        if (g_aimOn && s_localIdx > 0 && s_localIdx <= 64) {
            const uintptr_t maskAt = pawn + net::C_CSPlayerPawn::m_entitySpottedState
                                         + net::EntitySpottedState_t::m_bSpottedByMask;
            const uint32_t mask[2] = { Read<uint32_t>(maskAt), Read<uint32_t>(maskAt + 4) };
            const unsigned bit = static_cast<unsigned>(s_localIdx - 1);   // 64 bits, 0-based
            const bool maskVis = ((mask[bit >> 5] >> (bit & 31)) & 1u) != 0;
            visible = maskVis;

            // fast path: if the game's own per-frame trace already resolves
            // this pawn under the crosshair, we are looking straight at it —
            // visible now, without waiting out the mask's update cycle
            if (!visible && idEntHit)
                visible = true;
            if (visible) s_visMs[i] = GetTickCount();

            static DWORD s_visLog = 0;   // one raw-mask sample per second for verification
            if (GetTickCount() - s_visLog > 1000) {
                s_visLog = GetTickCount();
                const uint8_t spotted = Read<uint8_t>(
                    pawn + net::C_CSPlayerPawn::m_entitySpottedState
                        + net::EntitySpottedState_t::m_bSpotted);
                Logf("[vis] idx=%d localIdx=%d mask=[%08X,%08X] vis=%d spotted=%d ide=%d\n",
                     i, s_localIdx, mask[0], mask[1], visible ? 1 : 0, spotted ? 1 : 0,
                     idEnt);
            }

            // timestamp every visibility transition: the delay between an enemy
            // actually breaking/establishing line of sight and this edge is the
            // game's own spotted-mask latency, measured straight from memory
            static uint8_t s_prevVis[kMaxPlayers + 1] = {};
            const uint8_t visByte = maskVis ? 1 : 0;   // edges track the raw mask
            if (s_prevVis[i] != visByte) {
                Logf("[vis] edge idx=%d %u->%u t=%lu\n", i, s_prevVis[i], visByte,
                     GetTickCount());
                s_prevVis[i] = visByte;
            }
        }

        const Vec3 origin = Read<Vec3>(sceneNode + net::CGameSceneNode::m_vecAbsOrigin);
        Vec3 viewOffset = Read<Vec3>(pawn + net::C_BaseModelEntity::m_vecViewOffset);
        if (!(viewOffset.z > 16.0f && viewOffset.z < 110.0f))
            viewOffset.z = 64.0f;                      // fallback eye height if read looks wrong

        // Bone array: aim at the animated head bone instead of origin+viewOffset.
        // The head sits several units forward of the feet centre when a model leans
        // or turns — invisible when it faces us, but fully lateral on screen for a
        // player standing sideways, which was the sideways aiming error.
        const Vec3 eyePt{ origin.x, origin.y, origin.z + viewOffset.z };
        Vec3 head = eyePt;                          // fallback point
        Vec3 joints[kSkelN]{};
        float bx[kSkelN]{}, by[kSkelN]{};
        int   legBone[4] = { -1, -1, -1, -1 };   // picked kneeL/footL/kneeR/footR ids (-1 = synthetic)
        bool bonesOk = false, skelOk = false;
        const uintptr_t boneArr = Read<uintptr_t>(sceneNode + kBoneArrayOff);
        if (boneArr) {
            float hf[3]{};
            if (ReadBytes(boneArr + kBonePosOff + kBoneStride * kSkelJoints[kSkelHead],
                          hf, sizeof(hf))) {
                const Vec3 hb{ hf[0], hf[1], hf[2] };
                const float dx = hb.x - origin.x, dy = hb.y - origin.y, dz = hb.z - origin.z;
                if (dx > -48.0f && dx < 48.0f && dy > -48.0f && dy < 48.0f &&
                    dz > 0.0f && dz < 78.0f) {
                    // sane head position (NaN fails too). The lateral window
                    // covers sprint/strafe lean (~28 measured) with margin for
                    // side- and back-facing poses: rejecting a live pose makes
                    // the aim fall back to origin+eye — the sideways bug all
                    // over again.
                    // The point IS the head bone. It rides the face plane
                    // (~9 u forward of the spine), but anchoring x/y to the
                    // neck to dodge that offset put the head circle on the
                    // shoulder/backpack: in a lean or lunge the skull sits
                    // 15-25 u forward of the neck column. Face plane is on
                    // the head; the neck column isn't.
                    const Vec3 hp = hb;
                    head = hp;
                    joints[kSkelHead] = hp;
                    bonesOk = true;
                } else {
                    static DWORD s_boneLog = 0;   // 1 Hz: any pose the gate rejects
                    if (GetTickCount() - s_boneLog > 1000) {
                        s_boneLog = GetTickCount();
                        Logf("[bone] fail idx=%d d=(%.1f,%.1f,%.1f)\n", i, dx, dy, dz);
                    }
                }
            }
            // also read for the trigger target alone (its silhouette test
            // needs the joints even with the ESP master off) and for aimbot
            // enemies (the hitbox dropdown needs chest/pelvis joints)
            if (bonesOk && (g_espOn || i == trigSlot || ((g_aimOn || g_awOn) && enemy))) {
                uint8_t raw[kBoneReadBytes];
                if (ReadBytes(boneArr, raw, sizeof(raw))) {
                    skelOk = true;
                    for (int j = 0; j < kSkelKneeL; ++j) {   // spine+arms; legs are classified below
                        if (j == kSkelHead) continue;
                        float f[3];
                        memcpy(f, raw + kBonePosOff + kBoneStride * kSkelJoints[j], sizeof(f));
                        const Vec3 b{ f[0], f[1], f[2] };
                        const float ddx = b.x - origin.x, ddy = b.y - origin.y, ddz = b.z - origin.z;
                        if (!(ddx > -45.0f && ddx < 45.0f && ddy > -45.0f && ddy < 45.0f &&
                              ddz > -35.0f && ddz < 80.0f)) {  // NaN/inf land here too
                            // feet plunge below the origin on jump/land frames
                            // (measured: foot at −10.1 failed the old −10 floor
                            // and killed the whole skeleton) — lower bound is
                            // for those, garbage reads still fail the lateral
                            // window and the top
                            static DWORD s_skFailMs = 0;   // 1 Hz: which joint the gate rejects
                            if (GetTickCount() - s_skFailMs > 1000) {
                                s_skFailMs = GetTickCount();
                                Logf("[skel] fail j=%d b=%d d=(%.1f,%.1f,%.1f)\n",
                                     j, kSkelJoints[j], ddx, ddy, ddz);
                            }
                            skelOk = false;
                            break;
                        }
                        joints[j] = b;
                    }
                    // legs: knee/foot indices are the only table entries that
                    // differ per player model (dumps: one model reads knees
                    // 27/31 with a single floor bone at 28, another reads 27
                    // at neck height with floor bones 24/25), so classify them
                    // from the window geometry every frame:
                    //  - feet: every floor-level bone off the spine axis and
                    //    close to the pelvis is a candidate (foot and toe both
                    //    sit down there, and one planted foot leaves only one
                    //    side's pair); each candidate goes to the side whose
                    //    knee it sits under, and an empty side mirrors the
                    //    planted foot so the legs always split
                    //  - knees: the table pair when both read in the knee band
                    //    (0.35..0.95 of pelvis height), else the two lowest
                    //    bones in that band
                    // the sides then order by x with knee+foot swapping as a
                    // pair, so the shins never cross
                    if (skelOk) {
                        const int   nb  = (kBoneReadBytes - kBonePosOff) / kBoneStride;
                        const float px  = joints[kSkelPelv].x, py = joints[kSkelPelv].y;
                        const float pdz = joints[kSkelPelv].z - origin.z;
                        auto bPos = [&](int bi) {
                            float f[3]{};
                            memcpy(f, raw + kBonePosOff + kBoneStride * bi, sizeof(f));
                            return Vec3{ f[0], f[1], f[2] };
                        };
                        auto okRange = [&](const Vec3& b, float lo, float hi) {
                            const float sx = b.x - origin.x, sy = b.y - origin.y,
                                        sz = b.z - origin.z;
                            return sx > -45.0f && sx < 45.0f && sy > -45.0f && sy < 45.0f &&
                                   sz > lo && sz < hi;
                        };
                        auto nearP = [&](const Vec3& b) {
                            const float rx = b.x - px, ry = b.y - py;
                            return rx * rx + ry * ry < 28.0f * 28.0f;
                        };
                        // floor candidates: EVERY bone at foot height off the
                        // spine — a model can expose foot + toe together, or
                        // only one planted foot, and taking the first two in
                        // index order handed both sides the same leg (that is
                        // what merged the legs). Each candidate is assigned to
                        // the side whose knee it sits under below instead
                        int   feetC[6];
                        int   feetN = 0;
                        for (int bi = 0; bi < nb && feetN < 6; ++bi) {
                            const Vec3 b = bPos(bi);
                            if (!okRange(b, -12.0f, 10.0f) || !nearP(b)) continue;
                            const float sx = b.x - origin.x, sy = b.y - origin.y;
                            if (sx * sx + sy * sy < 9.0f) continue;   // spine axis: not a foot
                            feetC[feetN++] = bi;
                        }
                        auto isFoot = [&](int bi) {
                            for (int fc = 0; fc < feetN; ++fc)
                                if (feetC[fc] == bi) return true;
                            return false;
                        };
                        int kneeB[2] = { kBKneeL, kBKneeR };
                        auto isKnee = [&](int bi) {
                            if (bi < 0 || bi >= nb) return false;
                            const Vec3 b = bPos(bi);
                            const float sz = b.z - origin.z;
                            return okRange(b, -5.0f, pdz) && sz > pdz * 0.35f &&
                                   sz < pdz * 0.95f && nearP(b);
                        };
                        if (!isKnee(kneeB[0]) || !isKnee(kneeB[1])) {
                            int   best[2]  = { -1, -1 };
                            float bestZ[2] = { 1e9f, 1e9f };
                            for (int bi = 0; bi < nb; ++bi) {
                                if (isFoot(bi) || !isKnee(bi)) continue;
                                const float sz = bPos(bi).z - origin.z;
                                if (sz < bestZ[0]) {
                                    best[1] = best[0]; bestZ[1] = bestZ[0];
                                    best[0] = bi;      bestZ[0] = sz;
                                } else if (sz < bestZ[1]) {
                                    best[1] = bi;      bestZ[1] = sz;
                                }
                            }
                            kneeB[0] = best[0];
                            kneeB[1] = best[1];
                        }
                        Vec3 fp[2], kp[2];
                        if (kneeB[0] >= 0 && kneeB[1] >= 0) {
                            kp[0] = bPos(kneeB[0]);
                            kp[1] = bPos(kneeB[1]);
                        } else if (kneeB[0] >= 0 || kneeB[1] >= 0) {
                            kp[0] = bPos(kneeB[0] >= 0 ? kneeB[0] : kneeB[1]);
                            kp[1] = Vec3{ 2.0f * px - kp[0].x, 2.0f * py - kp[0].y, kp[0].z };
                        } else {
                            kneeB[0] = kneeB[1] = -1;
                            kp[0] = kp[1] = joints[kSkelPelv];   // no band bone: straight to the pelvis
                        }
                        // feet go to the side whose knee they sit under: foot
                        // and toe of one leg both vote for that side, so the
                        // other side mirrors the planted foot and the legs
                        // always split instead of merging into one
                        int   footB[2] = { -1, -1 };
                        float bestD[2] = { 1e9f, 1e9f };
                        for (int fc = 0; fc < feetN; ++fc) {
                            const Vec3 b = bPos(feetC[fc]);
                            const float dx0 = b.x - kp[0].x, dy0 = b.y - kp[0].y;
                            const float dx1 = b.x - kp[1].x, dy1 = b.y - kp[1].y;
                            const float d0 = dx0 * dx0 + dy0 * dy0;
                            const float d1 = dx1 * dx1 + dy1 * dy1;
                            const int   sd = d0 <= d1 ? 0 : 1;
                            const float dd = d0 <= d1 ? d0 : d1;
                            if (dd < bestD[sd]) { bestD[sd] = dd; footB[sd] = feetC[fc]; }
                        }
                        if (footB[0] >= 0 && footB[1] >= 0) {
                            fp[0] = bPos(footB[0]);
                            fp[1] = bPos(footB[1]);
                        } else if (footB[0] >= 0 || footB[1] >= 0) {
                            const int pl = footB[0] >= 0 ? 0 : 1;   // planted side
                            const int mi = 1 - pl;
                            fp[pl] = bPos(footB[pl]);
                            fp[mi] = Vec3{ 2.0f * px - fp[pl].x, 2.0f * py - fp[pl].y, fp[pl].z };
                            footB[mi] = -1;
                        } else {
                            // no floor bone this pose: plumb each shin to the ground under its knee
                            fp[0] = { kp[0].x, kp[0].y, origin.z };
                            fp[1] = { kp[1].x, kp[1].y, origin.z };
                            footB[0] = footB[1] = -1;
                        }
                        // order the SIDES together by x — knee and foot swap
                        // as one pair. Sorting them separately is what crossed
                        // the shins whenever the legs split along y instead
                        // of x (the pairs then disagreed about which side is
                        // which and drew an X)
                        if (kp[0].x > kp[1].x) {
                            const Vec3 t = kp[0]; kp[0] = kp[1]; kp[1] = t;
                            const Vec3 t2 = fp[0]; fp[0] = fp[1]; fp[1] = t2;
                            const int ti = kneeB[0]; kneeB[0] = kneeB[1]; kneeB[1] = ti;
                            const int tf = footB[0]; footB[0] = footB[1]; footB[1] = tf;
                        }
                        const Vec3 leg[4] = { kp[0], fp[0], kp[1], fp[1] };
                        for (int t = 0; t < 4; ++t) {
                            if (!okRange(leg[t], -35.0f, 80.0f)) {
                                static DWORD s_lgFailMs = 0;
                                if (GetTickCount() - s_lgFailMs > 1000) {
                                    s_lgFailMs = GetTickCount();
                                    Logf("[skel] leg fail t=%d d=(%.1f,%.1f,%.1f)\n", t,
                                         leg[t].x - origin.x, leg[t].y - origin.y,
                                         leg[t].z - origin.z);
                                }
                                skelOk = false;
                                break;
                            }
                            joints[kSkelKneeL + t] = leg[t];
                        }
                        legBone[0] = kneeB[0]; legBone[1] = footB[0];
                        legBone[2] = kneeB[1]; legBone[3] = footB[1];
                    }
                    // bone map dump: every transform by height above the feet
                    // and distance from the spine axis — geometry classifies
                    // joints, so a stale arm index after a model recompile
                    // shows up here instead of only as a wrong shape in-game
                    static DWORD s_boneDumpMs = 0;
                    static int   s_boneDumps  = 0;
                    if (skelOk && s_boneDumps < 12 &&
                        GetTickCount() - s_boneDumpMs > 6000) {
                        s_boneDumpMs = GetTickCount();
                        ++s_boneDumps;
                        const int nb = (kBoneReadBytes - kBonePosOff) / kBoneStride;
                        Logf("[bdbg] dump %d slot=%d\n", s_boneDumps, i);
                        for (int bi = 0; bi < nb; ++bi) {
                            float f[3];
                            memcpy(f, raw + kBonePosOff + kBoneStride * bi, sizeof(f));
                            const float dx = f[0] - origin.x, dy = f[1] - origin.y;
                            Logf("[bdbg]   b=%02d dz=%6.1f lat=%6.1f\n",
                                 bi, f[2] - origin.z, sqrtf(dx * dx + dy * dy));
                        }
                    }
                    // extended map dump: the 0..31 window holds hips and feet
                    // but no knees — the leg chain must live higher up. Signed
                    // dx,dy resolve left/right without knowing the facing.
                    static DWORD s_boneDump2Ms = 0;
                    static int   s_boneDumps2  = 0;
                    if (s_boneDumps2 < 6 &&
                        GetTickCount() - s_boneDump2Ms > 8000) {
                        uint8_t rawBig[0x2000];
                        if (ReadBytes(boneArr, rawBig, sizeof(rawBig))) {
                            s_boneDump2Ms = GetTickCount();
                            ++s_boneDumps2;
                            Logf("[bdbg2] dump %d slot=%d\n", s_boneDumps2, i);
                            for (int bi = 0; bi < 84; ++bi) {
                                float f[3];
                                memcpy(f, rawBig + kBonePosOff + kBoneStride * bi, sizeof(f));
                                Logf("[bdbg2]   b=%02d dx=%7.1f dy=%7.1f dz=%6.1f\n",
                                     bi, f[0] - origin.x, f[1] - origin.y, f[2] - origin.z);
                            }
                        }
                    }
                    if (skelOk) {
                        for (int j = 0; j < kSkelN; ++j) {
                            Vec3 js{};
                            if (!WorldToScreen(joints[j], js, vm)) {
                                static DWORD s_w2sMs = 0;   // 1 Hz: joint the projection drops
                                if (GetTickCount() - s_w2sMs > 1000) {
                                    s_w2sMs = GetTickCount();
                                    Logf("[skel] w2s fail j=%d b=%d\n", j, kSkelJoints[j]);
                                }
                                skelOk = false; break;
                            }
                            bx[j] = js.x;
                            by[j] = js.y;
                        }
                        // leg check: screen position AND world height of the
                        // pelvis/knee/foot joints, 1 Hz — if legs are missing
                        // this shows whether the bones read wrong (dz) or the
                        // projection puts them wrong (x,y)
                        static DWORD s_legMs = 0;
                        if (skelOk && GetTickCount() - s_legMs > 1000) {
                            s_legMs = GetTickCount();
                            Logf("[leg] i=%d pelvis=(%.0f,%.0f,dz%.0f) "
                                 "kneeL=(%.0f,%.0f,dz%.0f) footL=(%.0f,%.0f,dz%.0f) "
                                 "kneeR=(%.0f,%.0f,dz%.0f) footR=(%.0f,%.0f,dz%.0f)"
                                 " b=(%d,%d,%d,%d)\n",
                                 i, bx[kSkelPelv], by[kSkelPelv],
                                 joints[kSkelPelv].z - origin.z,
                                 bx[kSkelKneeL], by[kSkelKneeL],
                                 joints[kSkelKneeL].z - origin.z,
                                 bx[kSkelKneeL + 1], by[kSkelKneeL + 1],
                                 joints[kSkelKneeL + 1].z - origin.z,
                                 bx[kSkelKneeR], by[kSkelKneeR],
                                 joints[kSkelKneeR].z - origin.z,
                                 bx[kSkelKneeR + 1], by[kSkelKneeR + 1],
                                 joints[kSkelKneeR + 1].z - origin.z,
                                 legBone[0], legBone[1], legBone[2], legBone[3]);
                        }
                    }
                }
            }
        }

        // aim point: the head bone trimmed onto the capsule centre. Measured
        // across sessions: the joint sits ~1.5..2.5 ABOVE the capsule centre
        // (pose log dzB−vz ≈ +1.5 with eye ≈ centre; bone−4 landed at the
        // neck); horizontally it rides the face plane — kept, because the
        // neck-column anchor that used to replace it dropped the head circle
        // onto the shoulder/backpack whenever the model leaned. Every
        // sideways/neck miss came
        // from the EYE point — the camera stays over the feet while the model
        // leans forward along its facing, so side-on the eye line falls behind
        // the head — or from the old −(3+w) bias, never from the bone. One
        // constant trim; the point still rides every pose (crouch, lean, head-down)
        const float dzB = head.z - origin.z;   // raw joint height, for the log
        if (bonesOk) head.z -= 2.0f;
        else         head  = eyePt;            // bone failed: camera fallback (≈ centre upright)

        static DWORD s_poseMs = 0;   // 1 Hz: joint-vs-eye constant for re-tuning the trim
        if (GetTickCount() - s_poseMs > 1000) {
            s_poseMs = GetTickCount();
            Logf("[pose] idx=%d dzB=%.1f vz=%.1f\n", i, dzB, eyePt.z - origin.z);
        }

        // one model file name per second: the target list for parsing the real
        // head hitbox (bone + local capsule) straight out of the model — the
        // only pose-independent aim point, and the joint-vs-rendered-head
        // divergence in back views proves no constant trim can cover it
        static DWORD s_mdlMs = 0;
        if (GetTickCount() - s_mdlMs > 1000) {
            s_mdlMs = GetTickCount();
            const uintptr_t mp = Read<uintptr_t>(sceneNode + 0xA8);   // m_ModelName
            char nm[128]{};
            bool ok = mp > 0x10000 && mp < 0x7FFFFFFFFFFFULL && ReadBytes(mp, nm, 127);
            if (!ok && mp > 0x10000 && mp < 0x7FFFFFFFFFFFULL) {     // CUtlString indirection
                const uintptr_t mp2 = Read<uintptr_t>(mp);
                ok = mp2 > 0x10000 && mp2 < 0x7FFFFFFFFFFFULL && ReadBytes(mp2, nm, 127);
            }
            if (ok) for (int c = 0; c < 127; ++c) {
                if (nm[c] < 32 || nm[c] > 126) { nm[c] = 0; break; }
                if (c == 126) nm[127] = 0;
            }
            Logf("[model] idx=%d p=%p %s\n", i, reinterpret_cast<void*>(mp),
                 (ok && nm[0]) ? nm : "?");
        }

        Vec3 feetS{}, headS{};
        if (!WorldToScreen(head, headS, vm)) { ++nProj; continue; }
        if (!WorldToScreen(origin, feetS, vm)) {
            feetS.x = headS.x;   // origin behind the near plane: run the box off-screen
            feetS.y = static_cast<float>(g_height) + 60.0f;
        }
        // cull only when the WHOLE body is far outside: up close the feet
        // project hundreds of px below the viewport, and dropping the player
        // for that cost both the ESP and the lock at melee range. The trigger
        // target never culls — at melee range both points sit outside and it
        // used to lose exactly the target under the crosshair
        if (i != trigSlot &&
            (headS.y < -200.0f || headS.y > g_height + 200.0f)) {
            if (feetS.y < -200.0f || feetS.y > g_height + 200.0f) { ++nCull; continue; }
        }
        if (headS.x >= -50.0f && headS.x <= g_width + 50.0f) ++nOnScr;   // box actually intersects the viewport

        EspPlayer p{};
        p.feetX = feetS.x; p.feetY = feetS.y;
        p.headX = headS.x; p.headY = headS.y;
        p.headWX = head.x; p.headWY = head.y; p.headWZ = head.z;
        p.org = origin;
        p.slot = i;
        p.health = health;
        p.pawn = pawn; p.ctl = controller;
        p.weapDef = pdef;
        p.enemy  = enemy;
        p.visible = visible ||
                    (g_aimOn && GetTickCount() - s_visMs[i] <= kVisHoldMs);
        p.planting = planting;
        // flash timer while the helper's flash feature runs: live enemies get
        // tagged the moment their own screen goes white
        p.flashed = g_grFlashOn && g_grenFlashDur >= 0 &&
                    Read<float>(pawn + g_grenFlashDur) > 0.75f;
        p.bonesOk = bonesOk;
        p.skelOk  = skelOk;
        if (skelOk) {
            memcpy(p.bx, bx, sizeof(p.bx));
            memcpy(p.by, by, sizeof(p.by));
            memcpy(p.jw, joints, sizeof(p.jw));
        }
        if (g_espOn)  // name is display-only — skip its RPM on the fast aim path
            ReadBytes(controller + net::CBasePlayerController::m_iszPlayerName, p.name, sizeof(p.name) - 1);
        // autowall pick: the crosshair lies on a live enemy's projected figure
        // and nothing claimed the trigger yet — the game's wall-respecting ray
        // cannot see through cover, so this screen-space test is what hands
        // walled targets to aim and trigger
        if (g_awOn && enemy && trigSlot < 0 && CrosshairOnBox(p)) {
            trigSlot = i;
            g_trigAw = true;
            g_awSlot = i;
        }
        // the trigger target reached projection — hand its body box, joints,
        // health and range data to the triggerbot; if the projection failed
        // instead, g_trigCond simply stays false this frame and no press can
        // start on an unvalidatable target
        if ((g_triggerOn || g_revTg || g_awOn) && p.slot == trigSlot) {
            g_trigCond   = true;
            g_trigVisible = p.visible;
            g_trigHeadX = p.headX;  g_trigHeadY = p.headY;
            g_trigFeetX = p.feetX;  g_trigFeetY = p.feetY;
            g_trigSkelOk = p.skelOk;
            if (p.skelOk) {
                memcpy(g_trigBx, p.bx, sizeof(g_trigBx));
                memcpy(g_trigBy, p.by, sizeof(g_trigBy));
            }
            g_trigHp = p.health;
            g_trigPawn = pawn;
            // CS units are inches (72 u ≈ 1.83 m): 0.0254 m per unit; an
            // unreadable local origin reads back as 0 m and passes the gate
            g_trigDist = localOrgOk
                ? sqrtf((origin.x - localOrg.x) * (origin.x - localOrg.x) +
                        (origin.y - localOrg.y) * (origin.y - localOrg.y) +
                        (origin.z - localOrg.z) * (origin.z - localOrg.z)) * 0.0254f
                : 0.0f;
        }
        out.push_back(p);
    }

    // throttled summary: wall-clock based (~0.5 s) so the fast aim loop can't
    // inflate it, plus an immediate line whenever the kept count changes
    static DWORD s_lastLog  = 0;
    static int   s_lastKept = -1;
    const int    kept       = static_cast<int>(out.size());
    const DWORD  nowLog     = GetTickCount();
    const bool   periodic   = nowLog - s_lastLog > 500;
    if (periodic || kept != s_lastKept) {
        Logf("[collect] kept=%d onScr=%d | isLocal=%d dead=%d noHandle=%d noPawn=%d hp=%d life=%d team=%d mate=%d noNode=%d dorm=%d proj=%d cull=%d\n",
             kept, nOnScr, nIsLocal, nDead, nNoHandle, nNoPawn, nNoHealth, nLife, nTeam,
             nMate, nNoNode, nDormant, nProj, nCull);
        if (kept > 0)
            Logf("[collect] p0 feet=(%.0f,%.0f) head=(%.0f,%.0f) hp=%d en=%d\n",
                 out[0].feetX, out[0].feetY, out[0].headX, out[0].headY,
                 out[0].health, out[0].enemy);
        if (kept > 0 && periodic) {
            // deep snapshot: origin actually used + first matrix cells + sceneNode validity
            const uintptr_t lp = Read<uintptr_t>(g_client + off::dwLocalPlayerPawn);
            const uintptr_t list2 = Read<uintptr_t>(g_client + off::dwEntityList);
            (void)lp; (void)list2;
            Logf("[collect] vm[0..3]=(%.4f, %.4f, %.4f, %.4f)\n", vm[0], vm[1], vm[2], vm[3]);
            Logf("[collect] vm[12..15]=(%.4f, %.4f, %.4f, %.4f)\n", vm[12], vm[13], vm[14], vm[15]);
        }
        if (periodic) s_lastLog = nowLog;
        s_lastKept = kept;
    }
    return out;
}

// ---------------------------------------------------------------------------
// spectator list
// ---------------------------------------------------------------------------
// Walks the controller list and keeps every observer whose target handle
// resolves to the local pawn — that is, someone actually watching us. An
// observer in free roam carries no target, so it cannot be attributed to any
// player and is deliberately left out. Throttled to ~4 Hz: this feeds a name
// panel, not an aim path, and the scan costs four reads per occupied slot.
static void CollectSpectators() {
    static DWORD s_lastMs = 0;
    const DWORD  now = GetTickCount();
    if (now - s_lastMs < 250) return;
    s_lastMs = now;

    std::vector<Spectator> out;
    const uintptr_t entityList = Read<uintptr_t>(g_client + off::dwEntityList);
    const uintptr_t localPawn  = Read<uintptr_t>(g_client + off::dwLocalPlayerPawn);
    const uintptr_t localCtl   = Read<uintptr_t>(g_client + off::dwLocalPlayerController);
    if (entityList && localPawn) {
        const uint8_t localTeam = Read<uint8_t>(localPawn + net::C_BaseEntity::m_iTeamNum);

        // once a player is dead the game may move them onto a dedicated
        // observer pawn, so the observer state is looked for on BOTH pawns the
        // controller can hold: its normal pawn and m_hObserverPawn. The first
        // one reporting a live observer mode wins.
        const auto observerOf = [&](uintptr_t p, uintptr_t& svc, uint8_t& mode,
                                    uint32_t& tgt) {
            svc = 0; mode = 0; tgt = 0;
            if (!p) return;
            const uintptr_t s = Read<uintptr_t>(p + net::C_BasePlayerPawn::m_pObserverServices);
            if (!s) return;
            const uint8_t m = Read<uint8_t>(s + net::CPlayer_ObserverServices::m_iObserverMode);
            if (!m) return;
            svc  = s;
            mode = m;
            tgt  = Read<uint32_t>(s + net::CPlayer_ObserverServices::m_hObserverTarget);
        };

        static DWORD s_dbgMs = 0;
        const bool dbg = GetTickCount() - s_dbgMs >= 1000;
        if (dbg) s_dbgMs = GetTickCount();

        for (int i = 1; i <= kMaxPlayers; ++i) {
            const uintptr_t controller = EntityByIndex(entityList, static_cast<uint32_t>(i));
            if (!controller || controller == localCtl) continue;

            const uint32_t pawnHandle =
                Read<uint32_t>(controller + net::CCSPlayerController::m_hPlayerPawn);
            const uintptr_t pawn = pawnHandle
                ? EntityByIndex(entityList, pawnHandle & 0xFFFF) : 0;

            const uint32_t obsHandle =
                Read<uint32_t>(controller + net::CCSPlayerController::m_hObserverPawn);
            const uintptr_t obsPawn = (obsHandle & 0xFFFF)
                ? EntityByIndex(entityList, obsHandle & 0xFFFF) : 0;

            uintptr_t svc = 0; uint8_t mode = 0; uint32_t tgt = 0;
            observerOf(pawn, svc, mode, tgt);
            if (!mode) observerOf(obsPawn, svc, mode, tgt);

            // same reads the ESP uses: lifeState 0 = out on the map right now
            const uint8_t life = pawn ? Read<uint8_t>(pawn + net::C_BaseEntity::m_lifeState) : 1;
            const int     hp   = pawn ? Read<int>(pawn + net::C_BaseEntity::m_iHealth) : 0;

            if (dbg)
                Logf("[spec] dbg slot=%d pawn=%llX pSvc=%llX oPawn=%llX svc=%llX mode=%u tgt=%08X life=%u hp=%d\n",
                     i, static_cast<unsigned long long>(pawn),
                     static_cast<unsigned long long>(
                         pawn ? Read<uintptr_t>(pawn + net::C_BasePlayerPawn::m_pObserverServices) : 0),
                     static_cast<unsigned long long>(obsPawn),
                     static_cast<unsigned long long>(svc), mode, tgt,
                     static_cast<unsigned>(life), hp);

            if (!mode) continue;                       // not observing anyone
            const uintptr_t target = (tgt & 0xFFFF)
                ? EntityByIndex(entityList, tgt & 0xFFFF) : 0;
            if (target != localPawn) continue;         // watching someone else (or free)
            // A respawn can leave the old observer state behind on a
            // controller whose player is already alive on the map — the
            // services still say "watching you" while he is playing. Alive
            // means playing, not spectating, whatever the services claim.
            if (life == 0) continue;

            Spectator s{};
            s.slot = i;
            ReadBytes(controller + net::CBasePlayerController::m_iszPlayerName,
                      s.name, sizeof(s.name) - 1);
            s.name[sizeof(s.name) - 1] = '\0';
            s.mode  = mode;
            s.enemy = pawn && Read<uint8_t>(pawn + net::C_BaseEntity::m_iTeamNum) != localTeam;
            out.push_back(s);
        }
    }

    // only log a transition: the set is otherwise steady for whole rounds
    if (out.size() != g_specs.size()) {
        Logf("[spec] %d spectator(s)\n", static_cast<int>(out.size()));
        for (const Spectator& s : out)
            Logf("[spec]   %s slot=%d mode=%u %s\n",
                 s.name[0] ? s.name : "(no name)", s.slot, s.mode,
                 s.enemy ? "enemy" : "team");
    }
    g_specs = std::move(out);
}

// ---------------------------------------------------------------------------
// overlay drawing (background is pure black; black is the layer color key)
// ---------------------------------------------------------------------------
// 4x4 Bayer core of the 8x8 ordered dither used by the box fill brush
static const unsigned char kBayer4[4][4] = {
    { 0, 8, 2,10 }, {12, 4,14, 6 }, { 3,11, 1, 9 }, {15, 7,13, 5 }
};

// Pattern brush for the inside-box fill: an 8x8 indexed DIB whose palette is
// [color-key black, fill colour], with the Bayer threshold set to the opacity.
// Set pixels show the colour, clear pixels land on the layer's black key and
// fall through to the game — the pattern density IS the opacity, real
// translucency on a binary-alpha overlay. Rebuilt only when either input
// changes; the one cached brush stays owned here, callers just select it.
static HBRUSH BoxFillBrush() {
    static int    s_r = -1, s_g = -1, s_b = -1, s_opa = -1;
    static HBRUSH s_brush = nullptr;
    if (s_brush && s_r == g_colBoxFill.r && s_g == g_colBoxFill.g &&
        s_b == g_colBoxFill.b && s_opa == g_boxFillOpa) return s_brush;
    if (s_brush) { DeleteObject(s_brush); s_brush = nullptr; }

    struct {
        BITMAPINFOHEADER hdr;
        RGBQUAD          pal[2];
        unsigned char    bits[64];        // 8 rows x 8 px; the row is already DWORD-aligned
    } dib{};
    dib.hdr.biSize        = sizeof(BITMAPINFOHEADER);
    dib.hdr.biWidth       = 8;
    dib.hdr.biHeight      = 8;
    dib.hdr.biPlanes      = 1;
    dib.hdr.biBitCount    = 8;
    dib.hdr.biCompression = BI_RGB;
    dib.hdr.biClrUsed     = 2;
    dib.pal[0] = { 0, 0, 0, 0 };                       // the layer color key: see-through
    // pure black would alias pal[0] and erase the fill: floor to near-black
    const bool fillBlack = g_colBoxFill.r == 0 && g_colBoxFill.g == 0 && g_colBoxFill.b == 0;
    dib.pal[1] = { static_cast<BYTE>(fillBlack ? 1 : g_colBoxFill.b),
                   static_cast<BYTE>(fillBlack ? 1 : g_colBoxFill.g),
                   static_cast<BYTE>(fillBlack ? 1 : g_colBoxFill.r), 0 };

    const int thresh = (g_boxFillOpa * 64 + 50) / 100; // set pixels out of 64
    for (int y = 0; y < 8; ++y)
        for (int x = 0; x < 8; ++x) {
            const int m4  = kBayer4[y & 3][x & 3];
            const int off = (y < 4) ? (x < 4 ? 0 : 2) : (x < 4 ? 3 : 1);
            if (4 * m4 + off < thresh) dib.bits[y * 8 + x] = 1;   // 0..63, uniform
        }
    s_brush = CreateDIBPatternBrushPt(reinterpret_cast<const BITMAPINFO*>(&dib),
                                      DIB_RGB_COLORS);
    s_r = g_colBoxFill.r; s_g = g_colBoxFill.g; s_b = g_colBoxFill.b;
    s_opa = g_boxFillOpa;
    return s_brush;
}

// antialiased centered text: GDI DrawTextA has no smoothing, which is the
// crunchy look in screenshots. Callers keep their GDI path for no-GDI+.
static void AaText(HDC dc, const wchar_t* t, float x, float y, float w, float h,
                   float px, bool bold, COLORREF col) {
    Gdiplus::Graphics gfx(dc);
    Gdiplus::FontFamily ff(L"Tahoma");
    Gdiplus::Font f(&ff, (Gdiplus::REAL)px,
                    bold ? Gdiplus::FontStyleBold : Gdiplus::FontStyleRegular,
                    Gdiplus::UnitPixel);
    Gdiplus::StringFormat sf;
    sf.SetAlignment(Gdiplus::StringAlignmentCenter);
    sf.SetLineAlignment(Gdiplus::StringAlignmentCenter);
    Gdiplus::SolidBrush br(Gdiplus::Color(255, GetRValue(col), GetGValue(col), GetBValue(col)));
    gfx.DrawString(t, -1, &f, Gdiplus::RectF((Gdiplus::REAL)x, (Gdiplus::REAL)y,
                                             (Gdiplus::REAL)w, (Gdiplus::REAL)h), &sf, &br);
}

static void DrawEsp(HDC dc) {
    for (const EspPlayer& p : g_players) {
        const float boxH = p.feetY - p.headY;
        if (boxH < 4.0f) continue;

        float boxW = boxH * 0.45f;
        if (boxW < 5.0f) boxW = 5.0f;
        const float cx = (p.headX + p.feetX) * 0.5f;
        float rrTop = boxH * 0.11f;   // head-circle radius: box top sits on the
        if (rrTop < 3.0f)  rrTop = 3.0f;   // head, not its centre (matches the
                                            // skeleton's circle below); no fixed
                                            // cap — a zoomed head grows on screen
                                            // and the circle must grow with it

        const COLORREF color = p.enemy ? Cref(g_colBox) : RGB(80, 200, 255);
        HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(NULL_BRUSH));

        // box corners — also the anchor for the name/health text below, so they
        // exist whether or not the box itself is being drawn: head bone to feet
        const LONG l = static_cast<LONG>(cx - boxW * 0.5f);
        const LONG r = static_cast<LONG>(cx + boxW * 0.5f);
        const LONG t = static_cast<LONG>(p.headY - rrTop) - U(g_boxTopPad);  // headroom slider
        const LONG b = static_cast<LONG>(p.feetY);

        // silhouette glow: the humanoid is rebuilt from the projected joints —
        // fat round-cap strokes fuse into a body shape, so the halo hugs the
        // player instead of the box (reference: solid chams fill, glowing
        // contour outline). The outline is a color-key trick: a wide glow
        // stroke, then the same body in layer-black — black is the transparent
        // color key, so the interior punches back to see-through and only the
        // rim survives; the fill repaints that interior solid on top
        if (g_gdiplusTok && p.skelOk && (g_glowOutOn || (g_glowFillOn && p.enemy))) {
            Gdiplus::Graphics gfx(dc);
            gfx.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
            // outline ring thickness scales with its thickness bar
            float rim = boxH * 0.012f * g_glowOutThk;
            if (rim < 1.5f)  rim = 1.5f;
            if (rim > 8.0f)  rim = 8.0f;

            // one full pass of the body in `col`; `grow` widens every stroke
            // and the head so a pass can sit outside another pass, `thk` is
            // the row's thickness bar multiplying all limb widths
            const auto body = [&](const Gdiplus::Color& col, float grow, float thk) {
                // limb widths scale with the player's screen height so the blob
                // keeps body proportions at any range (floors stop far players
                // collapsing into hairlines)
                float torsoW = boxH * 0.16f * thk;
                float armW = boxH * 0.055f * thk;
                float legW = boxH * 0.075f * thk;
                float headR = boxH * 0.065f * thk;
                if (torsoW < 3.0f) torsoW = 3.0f;
                if (armW < 2.0f)   armW = 2.0f;
                if (legW < 2.5f)   legW = 2.5f;
                if (headR < 2.5f)  headR = 2.5f;
                Gdiplus::Pen pn(col, 1.0f);
                pn.SetLineCap(Gdiplus::LineCapRound, Gdiplus::LineCapRound,
                              Gdiplus::DashCapRound);
                pn.SetLineJoin(Gdiplus::LineJoinRound);
                const auto seg = [&](int a, int j, float w) {
                    pn.SetWidth(w + 2.0f * grow);
                    gfx.DrawLine(&pn, p.bx[a], p.by[a], p.bx[j], p.by[j]);
                };
                seg(1, 2, torsoW);                    // neck -> chest
                seg(2, 3, torsoW);                    // chest -> pelvis
                seg(4, 7, torsoW * 0.75f);            // shoulder bar
                seg(4, 5, armW);  seg(5, 6, armW);    // left arm
                seg(7, 8, armW);  seg(8, 9, armW);    // right arm
                seg(3, 10, legW); seg(10, 11, legW);  // left leg
                seg(3, 12, legW); seg(12, 13, legW);  // right leg
                const Gdiplus::SolidBrush hb(col);
                gfx.FillEllipse(&hb, p.headX - headR - grow, p.headY - headR - grow,
                                2.0f * (headR + grow), 2.0f * (headR + grow));
            };

            if (g_glowOutOn && g_glowOutOpa > 0) {
                const int oa = g_glowOutOpa;          // opacity bar, %
                body(Gdiplus::Color((BYTE)(70 * oa / 100), g_colGlowOut.r,
                                    g_colGlowOut.g, g_colGlowOut.b),
                     rim * 2.5f, g_glowOutThk);       // soft bloom
                body(Gdiplus::Color((BYTE)(235 * oa / 100), g_colGlowOut.r,
                                    g_colGlowOut.g, g_colGlowOut.b),
                     rim, g_glowOutThk);              // crisp rim
                body(Gdiplus::Color(255, 0, 0, 0), 0.0f,
                     g_glowOutThk);                   // punch interior transparent
            }
            if (g_glowFillOn && p.enemy && g_glowFillOpa > 0) {
                const int fa = g_glowFillOpa;
                const bool fillBlack = !g_colGlowFill.r && !g_colGlowFill.g &&
                                       !g_colGlowFill.b;
                body(Gdiplus::Color((BYTE)(255 * fa / 100),
                                    fillBlack ? 1 : g_colGlowFill.r,
                                    fillBlack ? 1 : g_colGlowFill.g,
                                    fillBlack ? 1 : g_colGlowFill.b),
                     0.0f, g_glowFillThk);
            }
        }

        // box and skeleton are separate toggles: each draws only while its own
        // switch is on (the wallhack master still gates the whole pass)
        HPEN    pen    = nullptr;
        HGDIOBJ oBoxPen = nullptr;
        if (g_boxOn) {
            // inside fill first, under the outline: the dithered pattern gives
            // the box its opacity (see BoxFillBrush), enemies only
            if (g_boxFillOn && p.enemy && g_boxFillOpa > 0) {
                HGDIOBJ oFill = SelectObject(dc, BoxFillBrush());
                HGDIOBJ oNP   = SelectObject(dc, GetStockObject(NULL_PEN));
                Rectangle(dc, l, t, r, b);
                SelectObject(dc, oNP);
                SelectObject(dc, oFill);
            }
            pen     = CreatePen(PS_SOLID, 2, color);
            oBoxPen = SelectObject(dc, pen);
            Rectangle(dc, l, t, r, b);
        }

        // skeleton: limbs as lines, head as a circle, drawn in its own colour
        // so it reads cleanly over the colored box (joint indices mapped from
        // live bone dumps; skipped when the bone read failed)
        if (p.skelOk && g_skelOn) {
            float rr = boxH * 0.11f;   // scales with the head at every zoom
            if (rr < 3.0f)  rr = 3.0f; // level — no fixed ceiling: scoping
                                       // magnifies the head on screen and the
                                       // circle has to follow it
            const float hcx = p.headX, hcy = p.headY;   // the aim point: the circle shows where it will shoot
            if (g_gdiplusTok) {
                // float pen width + antialiasing: 1.0 -> 1.1 -> 1.2 each lands
                // as genuinely wider edge coverage instead of rounding onto the
                // same whole-pixel GDI pen and jumping only every few steps.
                // AA blends against the overlay's black background (the color
                // key), so partial coverage shows as dimmed line colour.
                Gdiplus::Graphics gfx(dc);
                gfx.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
                const bool skelBlack = g_colSkel.r == 0 && g_colSkel.g == 0 && g_colSkel.b == 0;
                const Gdiplus::Pen sp(Gdiplus::Color(skelBlack ? 1 : g_colSkel.r,
                                                     skelBlack ? 1 : g_colSkel.g,
                                                     skelBlack ? 1 : g_colSkel.b),
                                      g_skelThick * UiScale());
                for (const auto& s : kSkelSegs)
                    gfx.DrawLine(&sp, p.bx[s[0]], p.by[s[0]], p.bx[s[1]], p.by[s[1]]);
                gfx.DrawEllipse(&sp, hcx - rr, hcy - rr, rr * 2.0f, rr * 2.0f);
            } else {
                // GDI+ unavailable: integer pen, width snaps between pixels
                HPEN skelPen  = CreatePen(PS_SOLID, U(g_skelThick), Cref(g_colSkel));
                HGDIOBJ oSPen = SelectObject(dc, skelPen);
                for (const auto& s : kSkelSegs) {
                    MoveToEx(dc, static_cast<LONG>(p.bx[s[0]]), static_cast<LONG>(p.by[s[0]]), nullptr);
                    LineTo(dc,   static_cast<LONG>(p.bx[s[1]]), static_cast<LONG>(p.by[s[1]]));
                }
                AaEllipseSel(dc, static_cast<LONG>(hcx - rr), static_cast<LONG>(hcy - rr),
                            static_cast<LONG>(hcx + rr), static_cast<LONG>(hcy + rr));
                SelectObject(dc, oSPen);
                DeleteObject(skelPen);
            }
        }

        if (pen) {
            SelectObject(dc, oBoxPen);
            DeleteObject(pen);
        }
        SelectObject(dc, oldBrush);

        // name above the box, health below it
        SetBkMode(dc, TRANSPARENT);
        const COLORREF hc = p.health > 50 ? RGB(120, 255, 120)
                          : p.health > 20 ? RGB(255, 210, 60)
                                          : RGB(255, 80, 80);
        if (g_gdiplusTok) {
            wchar_t wname[72], whp[16];
            swprintf_s(wname, L"%hs", p.name);
            swprintf_s(whp, L"%d", p.health);
            AaText(dc, wname, (float)cx - U(80), (float)t - U(18), (float)U(160), (float)U(16),
                   14.0f, true, RGB(255, 255, 255));
            AaText(dc, whp, (float)cx - U(80), (float)b + U(2), (float)U(160), (float)U(16),
                   14.0f, true, hc);
            continue;
        }
        HFONT font = MakeFont(14, FW_SEMIBOLD, "Tahoma");

        char healthText[16];
        sprintf_s(healthText, "%d", p.health);

        RECT nameRect{ static_cast<LONG>(cx) - U(80), t - U(18),
                       static_cast<LONG>(cx) + U(80), t - U(2) };
        RECT hpRect  { static_cast<LONG>(cx) - U(80), b + U(2),
                       static_cast<LONG>(cx) + U(80), b + U(18) };

        HGDIOBJ oldFont = SelectObject(dc, font);
        SetTextColor(dc, RGB(255, 255, 255));
        DrawTextA(dc, p.name, -1, &nameRect, DT_CENTER | DT_NOCLIP | DT_SINGLELINE);
        SetTextColor(dc, p.health > 50 ? RGB(120, 255, 120)
                     : p.health > 20 ? RGB(255, 210, 60)
                                     : RGB(255, 80, 80));
        if (g_wallHbText)
            DrawTextA(dc, healthText, -1, &hpRect, DT_CENTER | DT_NOCLIP | DT_SINGLELINE);
        SelectObject(dc, oldFont);
        DeleteObject(font);
    }
}

// ---------------------------------------------------------------------------
// in-game menu: drawn on the same overlay, input taken from global key/mouse
// state polling (works regardless of which window the OS routes clicks to)
// ---------------------------------------------------------------------------
struct MenuBox { int x, y, w, h; };

// Panel geometry vs control geometry: rows span the panel with a 12 px margin
// on each side (row from the panel width, 13 px square check box, 3 px slider
// track with a 7 px knob, label/track/value offsets all row-relative) — everything
// below is DESIGN px that U() converts for the display scale; the header band
// is the drag handle, the tab strip below it picks the feature section, and the
// panel keeps ONE fixed size on every tab — a section whose rows overflow
// the viewport scrolls them with the mouse wheel instead of growing the panel.
static const int kMenuW      = U(478);  // same shape as the reference menu: 478:420 ~= its 466:410
static const int kMenuH      = U(420);  // fixed panel height
static constexpr float kGuiScales[] = { 1.25f, 1.30f, 1.35f, 1.40f, 1.45f, 1.50f };
static constexpr int   kGuiScalePct[] = { 125, 130, 135, 140, 145, 150 };
static constexpr int   kGuiScaleN = 6;
static int             g_guiScale = 5;       // index into kGuiScales (default 150%)
static bool            g_guiDropOpen = false; // GUI Size list shown (UI thread only)
static bool            g_hitDropOpen = false; // trigger hit-groups list shown
// on-screen menu scale: the whole menu draws under this world transform
// (anchored at the panel origin), input runs in the same unscaled design
// space — the Misc tab's GUI Size dropdown picks the zoom live
static float MenuZoom() { return kGuiScales[g_guiScale]; }
static const int kMenuTitleH = U(46);   // header band — also the drag handle
static const int kTabH       = U(34);   // section band below the divider (holds the weapon combo)
static const int kMenuPitch  = U(24);   // row pitch: matches the reference's compact rows
static const int kMenuRowW   = kMenuW - 2 * U(12); // row width = panel minus margins
static const int kMenuRowH   = U(21);   // row height straight from the reference (23 px rows there)
static const int kMenuPadX   = U(12);   // control column's left margin
static const int kMenuPadB   = U(26);   // footer band: the hint under the row viewport
static const int kMenuRows   = 59;      // + trigger section, + enemy weapons-on-Tab row

// feature sections: rows keep their global indices (every handler keys off
// them) — a section lists which rows its tab shows, top to bottom; rows of
// other tabs park off-screen via MenuRow
enum { kSecWall = 0, kSecAim = 1, kSecGren = 2, kSecMisc = 3, kSecCfg = 4, kSecTrig = 5, kSecCount = 6 };
static constexpr int kSecRows[kSecCount][15] = {
    { 0, 14, 15, 42, 43, 8, 39, 58, -1, -1, -1, -1, -1, -1, -1 },    // Wallhack (eye):   master, box, skeleton, fill glow, outline glow, radar, tracers, weapons-on-Tab
    { 1, 2, 3, 9, 10, 37, 38, 27, -1, -1, -1, -1, -1, -1, -1 },      // AimHack (bullet): aimbot block, autowall, sniper settings
    { 31, 32, 33, 34, 35, 36, -1, -1, -1, -1, -1, -1, -1, -1, -1 },  // Grenades (pin):   esp, path, damage, flash, enemy-only, draw distance
    { 11, 12, 13, 18, 7, 20, 28, 41, 40, -1, -1, -1, -1, -1, -1 },   // Misc (gear):      auto bhop, jump mode, status, spectators, xhair, gui size, c4, hit log, log time
    { 21, 26, 22, 29, 23, 24, 25, -1, -1, -1, -1, -1, -1, -1, -1 },  // Configs (folder): picker, name, save, new, load, open folder, status
    { 4, 30, 27, 50, 51, 53, 54, 55, 56, 57, 16, 6, 5, 17, -1 }      // Trigger (bolt):   enable, revolver, sniper settings, gates, lock, delay, visible, groups, min dmg, chance, reaction, max dist
};
static constexpr int kSecN[kSecCount] = { 8, 8, 6, 9, 7, 14 };
static int g_sec = kSecWall;            // active tab (UI thread only)
static int g_menuScroll = 0;            // px the row list is scrolled up (mouse wheel)
static int g_menuScrollT = 0;           // scroll target: the wheel sets it, each frame glides toward it

// row membership by control type (row indices are global; kSecRows above
// decides which tab shows them) — toggles and sliders are drawn and hit-tested
// from these maps so each control keeps its own row
static constexpr int kToggleRow[24] = { 0, 1, 4, 7, 8, 9, 11, 14, 15, 18, 30,
                                        31, 32, 33, 34, 35, 37, 41, 42, 43,
                                        50, 51, 53, 58 };
static constexpr int kToggleN      = 24;
static constexpr int kSliderRow[17] = { 2, 3, 5, 6, 10, 16, 17, 19, 36, 38, 40,
                                        44, 45, 46, 47, 54, 55 };
static constexpr int   kSkelThickRow = 19;      // skeleton width bar (virtual row)
static constexpr float kSkelThickMin = 1.0f, kSkelThickMax = 5.0f;  // 0.1 steps
static constexpr int   kGlowFOpaRow = 44, kGlowFThkRow = 45;   // fill glow bars (virtual rows)
static constexpr int   kGlowOOpaRow = 46, kGlowOThkRow = 47;   // outline glow bars (virtual rows)
static constexpr int   kGlowOpaMin = 0, kGlowOpaMax = 100;     // glow opacity bars, %
static constexpr float kGlowThkMin = 0.5f, kGlowThkMax = 2.0f; // glow thickness bars, x (0.05 steps)
static constexpr int   kBoxOpaMin = 0, kBoxOpaMax = 100;  // box fill opacity slider, %
static constexpr int   kBoxBarsTop = 182;  // bar strip: after title + three card rows + top pad
static constexpr int   kBoxBarsH   = 88;   // its height (3 channel rows + padding)
static constexpr int kModeRow      = 12;  // Jump Mode dropdown
static constexpr int kGuiRow       = 20;  // GUI Size dropdown
static constexpr int kStatusRow    = 13;  // bhop status label
static constexpr int kCfgRow       = 21;  // config picker dropdown
static constexpr int kCfgNameRow    = 26;  // config name field
static constexpr int kCfgSaveRow   = 22;  // save button
static constexpr int kCfgNewRow    = 29;  // new-config button
static constexpr int kCfgLoadRow   = 23;  // load button
static constexpr int kCfgOpenRow   = 24;  // open-folder button
static constexpr int kCfgStatusRow = 25;  // last-action status label
static constexpr int kSniperRow    = 27;  // sniper settings button (opens its card)
static constexpr int kC4Row        = 28;  // C4 button (opens its card)
static constexpr int kGrenEspRow   = 31;  // grenade marker toggle
static constexpr int kGrenPathRow  = 32;  // trail + landing toggle
static constexpr int kGrenDmgRow   = 33;  // damage estimate toggle
static constexpr int kGrenFlashRow = 34;  // flashbang % toggle
static constexpr int kGrenEnemyRow = 35;  // enemy-grenades-only toggle
static constexpr int kGrenDistRow  = 36;  // draw distance slider
static constexpr int kAwRow        = 37;  // autowall toggle
static constexpr int kAwDmgRow     = 38;  // autowall min-damage slider
static constexpr int kHitLogRow    = 40;  // hit-feed lifetime slider (Misc)
static constexpr int kHitLogMin = 1, kHitLogMax = 10, kHitLogDft = 4;  // seconds
static int   g_hitLogLife = kHitLogDft;
static constexpr int kHitLogGuiRow = 41;  // hit-log history toggle (Misc)
static constexpr int kTrcRow       = 39;  // bullet tracers button (opens its card)
static constexpr int kTrigAirRow    = 50;  // air check toggle
static constexpr int kTrigScopeRow  = 51;  // auto scope mirror toggle
static constexpr int kTrigFlashRow  = 53;  // flash check toggle
static constexpr int kTrigLockRow   = 54;  // lock camera slider (ms)
static constexpr int kTrigGapRow    = 55;  // delay between shots slider (ms)
static constexpr int kTrigVisRow    = 56;  // visibility status label
static constexpr int kTrigGroupRow  = 57;  // hit groups dropdown
static constexpr int kTrigLockMin = 0, kTrigLockMax = 1000;
static constexpr int kTrigGapMin = 50, kTrigGapMax = 500;

// slot of a row inside the ACTIVE section, or -1 when it lives on another tab.
// The skeleton width row is virtual: it is inserted right after the skeleton
// row only while its button has it open, pushing radar/crosshair down a slot.
// The glow bar rows are virtual the same way, after their own glow rows.
static int ActiveSlot(int row) {
    int slot = 0;
    for (int s = 0; s < kSecN[g_sec]; ++s) {
        const int r = kSecRows[g_sec][s];
        if (r == row) return slot;
        ++slot;
        if (g_sec == kSecWall && g_skelThickOpen && r == 15) {
            if (row == kSkelThickRow) return slot;
            ++slot;
        }
        if (g_sec == kSecWall && g_glowFBarsOpen && r == 42) {
            if (row == kGlowFOpaRow) return slot;
            ++slot;
            if (row == kGlowFThkRow) return slot;
            ++slot;
        }
        if (g_sec == kSecWall && g_glowOBarsOpen && r == 43) {
            if (row == kGlowOOpaRow) return slot;
            ++slot;
            if (row == kGlowOThkRow) return slot;
            ++slot;
        }
    }
    return -1;
}
static bool RowShown(int row) { return ActiveSlot(row) >= 0; }

// A toggle whose feature can't act while some other toggle is off draws dim,
// so an inert ON state never reads as armed. The button itself still flips
// and is remembered — only its appearance says "needs its master on".
static bool RowDimmed(int row) {
    switch (row) {
    case 9:                      // FOV circle draws only while the aimbot is on
        return !g_aimOn;
    case 14: case 15:            // box and skeleton draw under the wallhack master
    case 42: case 43:            // fill and outline glow live inside DrawEsp too
        return !g_espOn;
    case 30:                     // revolver fires through the triggerbot
    case 49: case 50:            // through wall, air check: trigger conditions
    case 52: case 53:            // scope check and flash check likewise
        return !g_triggerOn;
    case 51:                     // autoscope zooms for aimbot or triggerbot
        return !g_aimOn && !g_triggerOn;
    case 35:                     // enemy-only filter: nothing to filter
        return !(g_grEspOn || g_grPathOn || g_grDmgOn || g_grFlashOn);
    default:
        return false;
    }
}

// fixed 16:9 panel: every tab is the same size — rows that don't fit scroll
// (mouse wheel over the panel) instead of the panel growing per section
static MenuBox MenuPanel() {
    return { g_menuPos.x, g_menuPos.y, kMenuW, kMenuH };
}
// safe mode toggle: pill in the header band, top-right of the panel — it sits
// outside every section (the header press below skips it, so clicking it never
// starts a panel drag)
static MenuBox SmHeaderBtn() {
    const MenuBox p = MenuPanel();
    const int w = U(132), h = U(26);
    return { p.x + p.w - U(14) - w, p.y + (kMenuTitleH - h) / 2, w, h };
}
static const int kSideW = U(108);   // sidebar rail: 108/478 = the reference's 105/466
// rows live in the content area right of the sidebar: every control is
// row-relative, so toggles, sliders, combos and swatches follow automatically
static MenuBox MenuRow(int i) {
    const MenuBox p = MenuPanel();
    const int slot = ActiveSlot(i);
    // a row from another tab parks far below the overlay: never drawn, never
    // hit — every existing handler keeps working unchanged
    const int y = slot >= 0 ? p.y + kMenuTitleH + kTabH + slot * kMenuPitch - g_menuScroll
                            : p.y + 100000;
    return { p.x + kSideW + kMenuPadX, y, kMenuRowW - kSideW, kMenuRowH };
}

// row viewport: the content band right of the sidebar — rows are clipped to
// it while drawing and only accept clicks inside it
static MenuBox MenuContent() {
    const MenuBox p = MenuPanel();
    return { p.x + kSideW, p.y + kMenuTitleH + kTabH, p.w - kSideW,
             kMenuH - kMenuTitleH - kTabH - kMenuPadB };
}
static int MenuMaxScroll() {
    int need = kSecN[g_sec] * kMenuPitch;
    if (g_sec == kSecWall) {           // open virtual bar rows push rows down
        if (g_skelThickOpen) need += kMenuPitch;
        if (g_glowFBarsOpen) need += 2 * kMenuPitch;
        if (g_glowOBarsOpen) need += 2 * kMenuPitch;
    }
    const int vis  = MenuContent().h;
    return need > vis ? need - vis : 0;
}
static void ClampMenuScroll() {
    if (g_menuScrollT < 0) g_menuScrollT = 0;
    if (g_menuScroll < 0) g_menuScroll = 0;
    const int maxS = MenuMaxScroll();
    if (g_menuScrollT > maxS) g_menuScrollT = maxS;
    if (g_menuScroll > maxS) g_menuScroll = maxS;
}
