// bar animation: every fill and knob eases toward its value instead of
// jumping — one smoothed follower per bar id (draw thread only), rate
// independent so the glide feels the same at any frame rate
struct BarAnim { int id; float v; DWORD ms; };
static BarAnim g_barAnim[48];
static int     g_barAnimN = 0;
static float SmoothBar(int id, float target) {
    BarAnim* a = nullptr;
    for (int i = 0; i < g_barAnimN; ++i)
        if (g_barAnim[i].id == id) { a = &g_barAnim[i]; break; }
    if (!a) {
        if (g_barAnimN >= 48) return target;     // table full: that bar stays instant
        a = &g_barAnim[g_barAnimN++];
        a->id = id;
        a->v  = target;                          // first sighting: start at the value
        a->ms = GetTickCount();
        return target;
    }
    const DWORD now = GetTickCount();
    float dts = (now - a->ms) / 1000.0f;
    a->ms = now;
    if (dts > 0.1f) dts = 0.1f;                  // hitch guard: one big step, no overshoot
    if (dts <= 0.0f) return a->v;
    a->v += (target - a->v) * (1.0f - expf(-dts * 16.0f));
    if (fabsf(target - a->v) < 0.002f) a->v = target;  // snap the last hair
    return a->v;
}

